n\",\"target\":\"https://www.limaviewtours.com/en/buscar?q={search_term_string}\",\"query-input\":\"required name=search_term_string\"}}]}','string','seo',NOW(),NOW()) ON DUPLICATE KEY UPDATE `value`=VALUES(`value`), updated_at=NOW();
INSERT INTO settings (`key`,`value`,`type`,`group`,created_at,updated_at) VALUES ('seo_page_home_schema_en','{\"@context\":\"https://schema.org\",\"@graph\":[{\"@type\":\"WebSite\",\"name\":\"Lima View Tours\",\"url\":\"https://www.limaviewtours.com/en\",\"inLanguage\":\"en\",\"potentialAction\":{\"@type\":\"SearchAction\",\"target\":\"https://www.limaviewtours.com/en/tours?q={search_term_string}\",\"query-input\":\"required name=search_term_string\"}},{\"@type\":\"FAQPage\",\"mainEntity\":[{\"@type\":\"Question\",\"name\":\"How do I book a tour?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Choose your tour, select the date and number of people, fill in your details and pay securely with PayPal or card. You will receive your confirmation by email instantly.\"}},{\"@type\":\"Question\",\"name\":\"Can I cancel or reschedule my booking?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Yes. You can cancel or reschedule up to 24 hours before the tour starts at no cost. Message us on WhatsApp and we will be glad to help.\"}},{\"@type\":\"Question\",\"name\":\"Is hotel pickup included?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"On most of our tours, pickup from your hotel or Airbnb is included within the coverage area. Just tell us the address when you book.\"}},{\"@type\":\"Question\",\"name\":\"What payment methods do you accept?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"We accept PayPal and all major credit and debit cards through a secure payment gateway.\"}},{\"@type\":\"Question\",\"name\":\"In which languages are the tours conducted?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"We have guides in Spanish and English. If you need another language, message us before booking and we will check availability.\"}},{\"@type\":\"Question\",\"name\":\"What does the tour price include?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"The price includes transport, a professional guide and the entrance fees listed in each tour. Personal expenses and tips are not included. Check the details on each experience\'s page.\"}}]}]}','string','seo',NOW(),NOW()) ON DUPLICATE KEY UPDATE `value`=VALUES(`value`), updated_at=NOW();
