INSERT INTO settings (`key`,`value`,`type`,`group`,created_at,updated_at) VALUES ('seo_page_home_schema_pt','{\"@context\":\"https://schema.org\",\"@graph\":[{\"@type\":\"WebSite\",\"name\":\"Lima View Tours\",\"url\":\"https://www.limaviewtours.com/pt\",\"inLanguage\":\"pt\",\"potentialAction\":{\"@type\":\"SearchAction\",\"target\":\"https://www.limaviewtours.com/pt/tours?q={search_term_string}\",\"query-input\":\"required name=search_term_string\"}},{\"@type\":\"FAQPage\",\"mainEntity\":[{\"@type\":\"Question\",\"name\":\"Como reservo um tour?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Escolha seu tour, selecione a data e o número de pessoas, preencha seus dados e pague com segurança via PayPal ou cartão. Você receberá a confirmação por e-mail na hora.\"}},{\"@type\":\"Question\",\"name\":\"Posso cancelar ou remarcar minha reserva?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Sim. Você pode cancelar ou remarcar até 24 horas antes do início do tour sem custo. Fale conosco pelo WhatsApp e teremos prazer em ajudar.\"}},{\"@type\":\"Question\",\"name\":\"O traslado do hotel está incluído?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Na maioria dos nossos tours, o traslado do seu hotel ou Airbnb está incluído dentro da área de cobertura. Basta informar o endereço ao reservar.\"}},{\"@type\":\"Question\",\"name\":\"Quais métodos de pagamento vocês aceitam?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Aceitamos PayPal e todos os principais cartões de crédito e débito através de um gateway de pagamento seguro.\"}},{\"@type\":\"Question\",\"name\":\"Em quais idiomas os tours são realizados?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Temos guias em espanhol e inglês. Se você precisar de outro idioma, fale conosco antes de reservar e verificaremos a disponibilidade.\"}},{\"@type\":\"Question\",\"name\":\"O que o preço do tour inclui?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"O preço inclui transporte, guia profissional e os ingressos indicados em cada tour. Despesas pessoais e gorjetas não estão incluídas. Confira os detalhes na página de cada experiência.\"}}]}]}','string','seo',NOW(),NOW()) ON DUPLICATE KEY UPDATE `value`=VALUES(`value`), updated_at=NOW();

UPDATE tours SET schema_jsonld_es='{\"@context\":\"https://schema.org\",\"@type\":[\"Product\",\"TouristTrip\"],\"@id\":\"https://www.limaviewtours.com/es/tours/detalle/full-day-lima-ancestral-colonial-y-moderna#tour\",\"name\":\"Full Day Lima: Centro Histórico, Pachacamac, Miraflores y Parque del Agua\",\"description\":\"Descubre la riqueza cultural y arqueológica de lima en este tour de dia completo. Visita el Santuario de Pachacamac, explora los encantadores distritos de Barranco y Miraflores, y maravíllate con la historia en el centro histórico. Finaliza con un espectáculo de luces en el parque de las aguas. Una...\",\"url\":\"https://www.limaviewtours.com/es/tours/detalle/full-day-lima-ancestral-colonial-y-moderna\",\"image\":[\"https://www.limaviewtours.com/storage/tours/gallery/01kwn8t2wfvpmw14xfpa6yz415.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwn8t359mxe2gznm6vsm6dg4.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwn8t3csgd66qd9d5yv6ryhr.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwn8t3mnrt8y8w5759gcgdp7.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwn8t3p8cpw1v19bxxfq01ws.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwn8t4x9qz0tgz1hmkbw6bj7.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwn8t55d8r8gjxpbw1hz85eh.webp\"],\"inLanguage\":\"es\",\"touristType\":[\"Sightseeing\",\"Cultural tourism\",\"Adventure\"],\"provider\":{\"@type\":\"TravelAgency\",\"name\":\"Lima View Tours\",\"url\":\"https://www.limaviewtours.com\",\"logo\":\"https://www.limaviewtours.com/assets/logos/logo.png\",\"telephone\":\"+51 925 886 725\"},\"aggregateRating\":{\"@type\":\"AggregateRating\",\"ratingValue\":5,\"reviewCount\":\"35\",\"bestRating\":5,\"worstRating\":1},\"itinerary\":{\"@type\":\"ItemList\",\"itemListElement\":[{\"@type\":\"ListItem\",\"position\":1,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Inicio en el hotel\",\"description\":\"Nos encontraremos en el lobby de tu hotel para iniciar nuestro recorrido\"}},{\"@type\":\"ListItem\",\"position\":2,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Santuario de Pachacamac\",\"description\":\"Exploraremos el Santuario de Pachacamac, un sitio arqueológico preincaico que fue un importante centro religioso y ceremonial. Descubre las ruinas de templos y pirámides mientras aprendes sobre la historia y la cultura de la región.\"}},{\"@type\":\"ListItem\",\"position\":3,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Barranco\",\"description\":\"Visitaremos el encantador distrito de Barranco, conocido por sus calles coloridas y su ambiente bohemio. Conoceremos el emblemático puente de los suspiros, una estructura de madera que ofrece vistas panorámicas del océano pacífico. También visitaremos la plaza de armas de barranco,su iglesia y monumentos cercanos.\"}},{\"@type\":\"ListItem\",\"position\":4,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Almuerzo en Barranco o Miraflores\",\"description\":\"Disfruta de un delicioso almuerzo en un restaurante local en Barranco o en el distrito vecino de Miraflores, donde podrás degustar la variada y exquisita gastronomía peruana. ( el amuerzo no esta incluido en el precio)\"}},{\"@type\":\"ListItem\",\"position\":5,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Miraflores\",\"description\":\"Exploraremos el distrito de Miraflores, uno de los más modernos y vibrantes de Lima. Conoceremos el Parque Kennedy, un lugar popular entre los lugareños y visitantes, y disfruta de su ambiente animado. Luego, visitaremos la Huaca Pucllana, un sitio arqueológico en medio de la ciudad que ofrece una fascinante visión de la historia pre-incaica.\"}},{\"@type\":\"ListItem\",\"position\":6,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Centro historico\",\"description\":\"Realizaremos un recorrido por el centro histórico de Lima, declarado patrimonio de la humanidad por la Unesco. Conoceran la Plaza de Armas, el corazón de la ciudad, donde se encuentran la Catedral de Lima, el Palacio de Gobierno y otros edificios históricos. También visitaremos el Convento de San francisco, famoso por sus Catacumbas subterráneas.\"}},{\"@type\":\"ListItem\",\"position\":7,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Parque de las Aguas\",\"description\":\"Terminaremos nuestro tour con una visita al Parque de las Aguas, un parque temático con espectaculares fuentes iluminadas. Disfrutaras de un espectáculo de agua y luz en un entorno mágico y relajante.\\r\\n\\r\\nEste itinerario te llevará a descubrir lo mejor de Lima, desde sus antiguas ruinas hasta sus modernos distritos, ofreciéndote una experiencia completa y memorable en la capital peruana.\"}},{\"@type\":\"ListItem\",\"position\":8,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Regreso al hotel\",\"description\":\"después de disfrutar de la belleza y la historia, regresaremos a tu hotel para concluir nuestro tour.\"}}]},\"offers\":{\"@type\":\"Offer\",\"price\":200,\"priceCurrency\":\"USD\",\"availability\":\"https://schema.org/InStock\",\"url\":\"https://www.limaviewtours.com/es/tours/detalle/full-day-lima-ancestral-colonial-y-moderna\",\"priceValidUntil\":\"2027-09-01\",\"validFrom\":\"2025-10-21\"}}' WHERE slug='full-day-lima-ancestral-colonial-y-moderna';
UPDATE tours SET schema_jsonld_en='{\"@context\":\"https://schema.org\",\"@type\":[\"Product\",\"TouristTrip\"],\"@id\":\"https://www.limaviewtours.com/en/tours/detalle/full-day-lima-ancestral-colonial-y-moderna#tour\",\"name\":\"Full Day Lima: Historic Center, Pachacamac, Miraflores and the Magic Water Circuit\",\"description\":\"Descubre la riqueza cultural y arqueológica de lima en este tour de dia completo. Visita el Santuario de Pachacamac, explora los encantadores distritos de Barranco y Miraflores, y maravíllate con la historia en el centro histórico. Finaliza con un espectáculo de luces en el parque de las aguas. Una...\",\"url\":\"https://www.limaviewtours.com/en/tours/detalle/full-day-lima-ancestral-colonial-y-moderna\",\"image\":[\"https://www.limaviewtours.com/storage/tours/gallery/01kwn8t2wfvpmw14xfpa6yz415.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwn8t359mxe2gznm6vsm6dg4.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwn8t3csgd66qd9d5yv6ryhr.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwn8t3mnrt8y8w5759gcgdp7.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwn8t3p8cpw1v19bxxfq01ws.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwn8t4x9qz0tgz1hmkbw6bj7.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwn8t55d8r8gjxpbw1hz85eh.webp\"],\"inLanguage\":\"en\",\"touristType\":[\"Sightseeing\",\"Cultural tourism\",\"Adventure\"],\"provider\":{\"@type\":\"TravelAgency\",\"name\":\"Lima View Tours\",\"url\":\"https://www.limaviewtours.com\",\"logo\":\"https://www.limaviewtours.com/assets/logos/logo.png\",\"telephone\":\"+51 925 886 725\"},\"aggregateRating\":{\"@type\":\"AggregateRating\",\"ratingValue\":5,\"reviewCount\":\"35\",\"bestRating\":5,\"worstRating\":1},\"itinerary\":{\"@type\":\"ItemList\",\"itemListElement\":[{\"@type\":\"ListItem\",\"position\":1,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Hotel Departure\",\"description\":\"We will meet you in your hotel lobby to begin our tour.\"}},{\"@type\":\"ListItem\",\"position\":2,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Pachacamac Sanctuary\",\"description\":\"We will explore the Sanctuary of Pachacamac, a pre-Inca archaeological site that served as an important religious and ceremonial center. Discover the ruins of temples and pyramids while learning about the history and culture of the region.\"}},{\"@type\":\"ListItem\",\"position\":3,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Barranco\",\"description\":\"We will visit the charming district of Barranco, known for its colorful streets and bohemian atmosphere. We will see the iconic Bridge of Sighs, a wooden structure offering panoramic views of the Pacific Ocean. We will also visit Barranco\'s main square, its church, and nearby monuments.\"}},{\"@type\":\"ListItem\",\"position\":4,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Lunch in Barranco or Miraflores\",\"description\":\"Enjoy a delicious lunch at a local restaurant in Barranco or the neighboring district of Miraflores, where you can savor the varied and exquisite Peruvian cuisine.\"}},{\"@type\":\"ListItem\",\"position\":5,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Miraflores\",\"description\":\"We will explore the district of Miraflores, one of Lima\'s most modern and vibrant neighborhoods. We will visit Parque Kennedy, a popular spot among locals and visitors, and enjoy its lively atmosphere. Then, we will head to Huaca Pucllana, an archaeological site in the heart of the city that offers a fascinating glimpse into pre-Inca history.\"}},{\"@type\":\"ListItem\",\"position\":6,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Lima City Tour\",\"description\":\"We will tour Lima\'s historic center, a UNESCO World Heritage Site. You will see the Plaza de Armas, the heart of the city, home to Lima Cathedral, the Government Palace, and other historic buildings. We will also visit the Convent of San Francisco, famous for its underground Catacombs.\"}},{\"@type\":\"ListItem\",\"position\":7,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Parque de las Aguas\",\"description\":\"We will end our tour with a visit to the Parque de las Aguas, a theme park featuring spectacular illuminated fountains. Enjoy a dazzling water and light show in a magical and relaxing setting.\\r\\n\\r\\nThis itinerary will take you to discover the best of Lima, from its ancient ruins to its modern districts, offering you a complete and memorable experience in the Peruvian capital.\"}},{\"@type\":\"ListItem\",\"position\":8,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Return to Hotel\",\"description\":\"After enjoying the beauty and history, we will return you to your hotel to conclude our tour.\"}}]},\"offers\":{\"@type\":\"Offer\",\"price\":200,\"priceCurrency\":\"USD\",\"availability\":\"https://schema.org/InStock\",\"url\":\"https://www.limaviewtours.com/en/tours/detalle/full-day-lima-ancestral-colonial-y-moderna\",\"priceValidUntil\":\"2027-09-01\",\"validFrom\":\"2025-10-21\"}}' WHERE slug='full-day-lima-ancestral-colonial-y-moderna';
UPDATE tours SET schema_jsonld_pt='{\"@context\":\"https://schema.org\",\"@type\":[\"Product\",\"TouristTrip\"],\"@id\":\"https://www.limaviewtours.com/pt/tours/detalle/full-day-lima-ancestral-colonial-y-moderna#tour\",\"name\":\"Full Day Lima: Centro Histórico, Pachacamac, Miraflores e Parque das Águas\",\"description\":\"Descubre la riqueza cultural y arqueológica de lima en este tour de dia completo. Visita el Santuario de Pachacamac, explora los encantadores distritos de Barranco y Miraflores, y maravíllate con la historia en el centro histórico. Finaliza con un espectáculo de luces en el parque de las aguas. Una...\",\"url\":\"https://www.limaviewtours.com/pt/tours/detalle/full-day-lima-ancestral-colonial-y-moderna\",\"image\":[\"https://www.limaviewtours.com/storage/tours/gallery/01kwn8t2wfvpmw14xfpa6yz415.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwn8t359mxe2gznm6vsm6dg4.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwn8t3csgd66qd9d5yv6ryhr.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwn8t3mnrt8y8w5759gcgdp7.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwn8t3p8cpw1v19bxxfq01ws.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwn8t4x9qz0tgz1hmkbw6bj7.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwn8t55d8r8gjxpbw1hz85eh.webp\"],\"inLanguage\":\"pt\",\"touristType\":[\"Sightseeing\",\"Cultural tourism\",\"Adventure\"],\"provider\":{\"@type\":\"TravelAgency\",\"name\":\"Lima View Tours\",\"url\":\"https://www.limaviewtours.com\",\"logo\":\"https://www.limaviewtours.com/assets/logos/logo.png\",\"telephone\":\"+51 925 886 725\"},\"aggregateRating\":{\"@type\":\"AggregateRating\",\"ratingValue\":5,\"reviewCount\":\"35\",\"bestRating\":5,\"worstRating\":1},\"itinerary\":{\"@type\":\"ItemList\",\"itemListElement\":[{\"@type\":\"ListItem\",\"position\":1,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Partida do hotel\",\"description\":\"Nos encontraremos no lobby do seu hotel para iniciar nosso passeio.\"}},{\"@type\":\"ListItem\",\"position\":2,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Santuário de Pachacamac\",\"description\":\"Exploraremos o Santuário de Pachacamac, um sítio arqueológico pré-inca que foi um importante centro religioso e cerimonial. Descubra as ruínas de templos e pirâmides enquanto aprende sobre a história e a cultura da região.\"}},{\"@type\":\"ListItem\",\"position\":3,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Barranco\",\"description\":\"Visitaremos o encantador bairro de Barranco, conhecido por suas ruas coloridas e atmosfera boêmia. Conheceremos a emblemática Ponte dos Suspiros, uma estrutura de madeira que oferece vistas panorâmicas do Oceano Pacífico. Também visitaremos a praça principal de Barranco, sua igreja e monumentos próximos.\"}},{\"@type\":\"ListItem\",\"position\":4,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Almoço em Barranco ou Miraflores\",\"description\":\"Desfrute de um delicioso almoço em um restaurante local em Barranco ou no bairro vizinho de Miraflores, onde você poderá saborear a variada e requintada gastronomia peruana.\"}},{\"@type\":\"ListItem\",\"position\":5,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Miraflores\",\"description\":\"Exploraremos o bairro de Miraflores, um dos mais modernos e vibrantes de Lima. Conheceremos o Parque Kennedy, um local popular entre moradores e visitantes, e aproveite sua atmosfera animada. Em seguida, visitaremos a Huaca Pucllana, um sítio arqueológico no meio da cidade que oferece uma visão fascinante da história pré-inca.\"}},{\"@type\":\"ListItem\",\"position\":6,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"City tour Lima\",\"description\":\"Realizaremos um passeio pelo centro histórico de Lima, declarado Patrimônio da Humanidade pela Unesco. Você conhecerá a Plaza de Armas, o coração da cidade, onde se encontram a Catedral de Lima, o Palácio do Governo e outros edifícios históricos. Também visitaremos o Convento de São Francisco, famoso pelas suas Catacumbas subterrâneas.\"}},{\"@type\":\"ListItem\",\"position\":7,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Parque das Águas\",\"description\":\"Encerraremos nosso tour com uma visita ao Parque das Águas, um parque temático com espetaculares fontes iluminadas. Desfrute de um show de água e luz em um ambiente mágico e relaxante.\\r\\n\\r\\nEste roteiro levará você a descobrir o melhor de Lima, desde suas ruínas antigas até seus bairros modernos, proporcionando uma experiência completa e inesquecível na capital peruana.\"}},{\"@type\":\"ListItem\",\"position\":8,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Retorno ao hotel\",\"description\":\"Após desfrutar da beleza e da história, retornaremos ao seu hotel para encerrar nosso tour.\"}}]},\"offers\":{\"@type\":\"Offer\",\"price\":200,\"priceCurrency\":\"USD\",\"availability\":\"https://schema.org/InStock\",\"url\":\"https://www.limaviewtours.com/pt/tours/detalle/full-day-lima-ancestral-colonial-y-moderna\",\"priceValidUntil\":\"2027-09-01\",\"validFrom\":\"2025-10-21\"}}' WHERE slug='full-day-lima-ancestral-colonial-y-moderna';
