UPDATE tours SET schema_jsonld_es='{\"@context\":\"https://schema.org\",\"@type\":[\"Product\",\"TouristTrip\"],\"@id\":\"https://www.limaviewtours.com/es/tours/detalle/tour-de-dia-completo-al-oasis-de-huacachina-islas-ballestas-en-paracas-2#tour\",\"name\":\"TOUR DE DIA COMPLETO AL OASIS DE HUACACHINA + ISLAS BALLESTAS EN PARACAS\",\"description\":\"Te llevaremos a Huacachina para que explores sus impresionantes dunas de arena, disfrutes de un emocionante paseo en buggy por sus empinadas laderas y experimentes la emoción del sandboarding. Con su combinación única de adrenalina y belleza natural, huacachina ofrece una experiencia inolvidable en...\",\"url\":\"https://www.limaviewtours.com/es/tours/detalle/tour-de-dia-completo-al-oasis-de-huacachina-islas-ballestas-en-paracas-2\",\"image\":[\"https://www.limaviewtours.com/storage/tours/gallery/01kwf99t1cnk316xa1bd53yr61.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwf8m1e0hkdzsszfcpc4tqdb.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwf8kvhv29tvz47mx6gd3psz.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwf8kx7we469vgmnxgw903re.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwf8kxxj6c359q43hd78e1z0.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwf8m08203nr083tga34mf50.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwf8kyx5rngvf2fgh3051my6.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwf8kvadre6fkq85pf077b83.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwf8kvrcfx8agpgkm2m655te.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwf8kvzpy8t99v5rhzrwb8k9.webp\"],\"inLanguage\":\"es\",\"touristType\":[\"Sightseeing\",\"Cultural tourism\",\"Adventure\"],\"provider\":{\"@type\":\"TravelAgency\",\"name\":\"Lima View Tours\",\"url\":\"https://www.limaviewtours.com\",\"logo\":\"https://www.limaviewtours.com/assets/logos/logo.png\",\"telephone\":\"+51 925 886 725\"},\"aggregateRating\":{\"@type\":\"AggregateRating\",\"ratingValue\":5,\"reviewCount\":\"55\",\"bestRating\":5,\"worstRating\":1},\"review\":[{\"@type\":\"Review\",\"author\":{\"@type\":\"Person\",\"name\":\"Dayanne Herrera villanueva\"},\"datePublished\":\"2026-07-01\",\"reviewRating\":{\"@type\":\"Rating\",\"ratingValue\":5,\"bestRating\":5},\"reviewBody\":\"Excelente servicio. Fueron muy puntuales para nuestro tour a Islas Ballestas y Huacachina. Posteriormente les solicité información y apoyo para organizar tours en Cusco, y nuevamente recibí una atención excelente.\\n\\nTodo se manejó con gran profesionalismo, los horarios se respetaron en todo momento y los guías siempre fueron muy amables y atentos. Sin duda recomiendo esta agencia por su excelente organización y servicio al cliente.\"},{\"@type\":\"Review\",\"author\":{\"@type\":\"Person\",\"name\":\"Walter Cuadra \"},\"datePublished\":\"2026-06-27\",\"reviewRating\":{\"@type\":\"Rating\",\"ratingValue\":5,\"bestRating\":5},\"reviewBody\":\"Fizemos o passeio de Paracas + Huacachina com a agencia, e foi tudo certo, o guia era ótimo, O passeio é maravilhoso\"},{\"@type\":\"Review\",\"author\":{\"@type\":\"Person\",\"name\":\"yinet santos alcantara\"},\"datePublished\":\"2026-06-26\",\"reviewRating\":{\"@type\":\"Rating\",\"ratingValue\":5,\"bestRating\":5},\"reviewBody\":\"⭐️⭐️⭐️⭐️⭐️ “Una experiencia inolvidable en Huacachina”\\nDesde el primer momento el trato fue excelente. El equipo fue muy amable, puntual y siempre atento a cada detalle. Nos explicaron todo con paciencia y buena vibra, haciendo que el tour fuera muy divertido y seguro. El paseo en los buggies por las dunas fue increíble, y el sandboard una experiencia única. Además, se nota que se preocupan por el bienestar del grupo y porque todos disfruten. ¡Definitivamente lo recomiendo al 100%! Fue uno...\"}],\"itinerary\":{\"@type\":\"ItemList\",\"itemListElement\":[{\"@type\":\"ListItem\",\"position\":1,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Recojo a hotel\"}},{\"@type\":\"ListItem\",\"position\":2,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Realizaremos una breve parada para poder\",\"description\":\"Realizaremos una breve parada para poder tomar desayuno\"}},{\"@type\":\"ListItem\",\"position\":3,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Islas Ballestas llegada al muelle\",\"description\":\"Islas Ballestas llegada al muelle turístico donde iniciaremos nuestra excursión hacia las Islas Ballestas , en este recorrido haremos un paseoen el deslizador, es aquí donde podran apreciar El Candelabro, que es un geoglifo de grandes dimensiones muy similares a las Líneas de Nazca. Esta isla esta hecha naturalmente de formaciones rocosas que albergan una importante fauna marina, donde habitan grandes colonias de aves guaneras (Guanay, Piquero, Pelícano, Cormoran, Zarcillos, etc.) Tambien podremos visualizar Lobos Marinos, Pingüinos de Humboldt y con un poco de suerte Delfines.\"}},{\"@type\":\"ListItem\",\"position\":4,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Almuerzo llegamos a Ica para almorzar\",\"description\":\"tiempo libre), podremos disfrutar de algunos platos típicos como “La Ruta del Pisco”, arroz con pato, sopa seca, ceviche y otros platos\"}},{\"@type\":\"ListItem\",\"position\":5,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Visita a la vitivinivola y degustación\",\"description\":\"Bodega Nietto) haremos un recorrido hacia la bodega para poder conocer la elaboración de un buen pisco, luego pasaremos a degustar, vinos, cremas de pisco, macerados y pisco todo ya incluido en nuestro servicio, los que deseen pueden comprar\"}},{\"@type\":\"ListItem\",\"position\":6,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Visita al Oasis Huacachina y Dunas\",\"description\":\"visita al Oasis Huacachina y Dunas ¡Descubriremos la emoción en Duacachina! Una experiencia única en el oasis mas grande de sudamérica.\"}},{\"@type\":\"ListItem\",\"position\":7,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Buggies en el desierto\",\"description\":\"experimentaremos la emoción de recorrer las dunas en nuestros vehículos todo terreno, conducidos por expertos choferes que te llevarán a través Las Dunas de Arena a toda velocidad para disfrutar de vistas panorámicas impresionantes.\"}},{\"@type\":\"ListItem\",\"position\":8,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Sandboarding\",\"description\":\"dominaremos las dunas con nuestro equipo de sandboarding y nos deslízaremos por las pendientes en una tabla especialmente diseñada para la arena, sin duda es una experiencia emocionante que no te puedes perder.\"}},{\"@type\":\"ListItem\",\"position\":9,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Retorno a lima\"}},{\"@type\":\"ListItem\",\"position\":10,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Llegada a su hotel\"}}]},\"offers\":{\"@type\":\"Offer\",\"price\":60,\"priceCurrency\":\"USD\",\"availability\":\"https://schema.org/InStock\",\"url\":\"https://www.limaviewtours.com/es/tours/detalle/tour-de-dia-completo-al-oasis-de-huacachina-islas-ballestas-en-paracas-2\",\"priceValidUntil\":\"2027-09-01\",\"validFrom\":\"2025-10-16\"}}' WHERE slug='tour-de-dia-completo-al-oasis-de-huacachina-islas-ballestas-en-paracas-2';
UPDATE tours SET schema_jsonld_en='{\"@context\":\"https://schema.org\",\"@type\":[\"Product\",\"TouristTrip\"],\"@id\":\"https://www.limaviewtours.com/en/tours/detalle/tour-de-dia-completo-al-oasis-de-huacachina-islas-ballestas-en-paracas-2#tour\",\"name\":\"FULL-DAY TOUR TO THE HUACACHINA OASIS + BALLESTAS ISLANDS IN PARACAS\",\"description\":\"Te llevaremos a Huacachina para que explores sus impresionantes dunas de arena, disfrutes de un emocionante paseo en buggy por sus empinadas laderas y experimentes la emoción del sandboarding. Con su combinación única de adrenalina y belleza natural, huacachina ofrece una experiencia inolvidable en...\",\"url\":\"https://www.limaviewtours.com/en/tours/detalle/tour-de-dia-completo-al-oasis-de-huacachina-islas-ballestas-en-paracas-2\",\"image\":[\"https://www.limaviewtours.com/storage/tours/gallery/01kwf99t1cnk316xa1bd53yr61.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwf8m1e0hkdzsszfcpc4tqdb.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwf8kvhv29tvz47mx6gd3psz.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwf8kx7we469vgmnxgw903re.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwf8kxxj6c359q43hd78e1z0.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwf8m08203nr083tga34mf50.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwf8kyx5rngvf2fgh3051my6.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwf8kvadre6fkq85pf077b83.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwf8kvrcfx8agpgkm2m655te.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwf8kvzpy8t99v5rhzrwb8k9.webp\"],\"inLanguage\":\"en\",\"touristType\":[\"Sightseeing\",\"Cultural tourism\",\"Adventure\"],\"provider\":{\"@type\":\"TravelAgency\",\"name\":\"Lima View Tours\",\"url\":\"https://www.limaviewtours.com\",\"logo\":\"https://www.limaviewtours.com/assets/logos/logo.png\",\"telephone\":\"+51 925 886 725\"},\"aggregateRating\":{\"@type\":\"AggregateRating\",\"ratingValue\":5,\"reviewCount\":\"55\",\"bestRating\":5,\"worstRating\":1},\"review\":[{\"@type\":\"Review\",\"author\":{\"@type\":\"Person\",\"name\":\"Dayanne Herrera villanueva\"},\"datePublished\":\"2026-07-01\",\"reviewRating\":{\"@type\":\"Rating\",\"ratingValue\":5,\"bestRating\":5},\"reviewBody\":\"Excelente servicio. Fueron muy puntuales para nuestro tour a Islas Ballestas y Huacachina. Posteriormente les solicité información y apoyo para organizar tours en Cusco, y nuevamente recibí una atención excelente.\\n\\nTodo se manejó con gran profesionalismo, los horarios se respetaron en todo momento y los guías siempre fueron muy amables y atentos. Sin duda recomiendo esta agencia por su excelente organización y servicio al cliente.\"},{\"@type\":\"Review\",\"author\":{\"@type\":\"Person\",\"name\":\"Walter Cuadra \"},\"datePublished\":\"2026-06-27\",\"reviewRating\":{\"@type\":\"Rating\",\"ratingValue\":5,\"bestRating\":5},\"reviewBody\":\"Fizemos o passeio de Paracas + Huacachina com a agencia, e foi tudo certo, o guia era ótimo, O passeio é maravilhoso\"},{\"@type\":\"Review\",\"author\":{\"@type\":\"Person\",\"name\":\"yinet santos alcantara\"},\"datePublished\":\"2026-06-26\",\"reviewRating\":{\"@type\":\"Rating\",\"ratingValue\":5,\"bestRating\":5},\"reviewBody\":\"⭐️⭐️⭐️⭐️⭐️ “Una experiencia inolvidable en Huacachina”\\nDesde el primer momento el trato fue excelente. El equipo fue muy amable, puntual y siempre atento a cada detalle. Nos explicaron todo con paciencia y buena vibra, haciendo que el tour fuera muy divertido y seguro. El paseo en los buggies por las dunas fue increíble, y el sandboard una experiencia única. Además, se nota que se preocupan por el bienestar del grupo y porque todos disfruten. ¡Definitivamente lo recomiendo al 100%! Fue uno...\"}],\"itinerary\":{\"@type\":\"ItemList\",\"itemListElement\":[{\"@type\":\"ListItem\",\"position\":1,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Hotel pickup\"}},{\"@type\":\"ListItem\",\"position\":2,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"We will make a brief stop to have\",\"description\":\"We will make a brief stop to have breakfast\"}},{\"@type\":\"ListItem\",\"position\":3,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Ballestas Islands\",\"description\":\"arrival at the tourist pier where we will begin our excursion to the Ballestas Islands. During this trip we will take a boat ride, where you will be able to admire El Candelabro, a large-scale geoglyph very similar to the Nazca Lines. These islands are made up of natural rock formations that shelter an important marine fauna, home to large colonies of guano birds (Guanay cormorant, Peruvian booby, Pelican, Cormorant, Inca terns, etc.). We will also be able to spot Sea Lions, Humboldt Penguins and, with a bit of luck, Dolphins\"}},{\"@type\":\"ListItem\",\"position\":4,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Lunch\",\"description\":\"we arrive in Ica for lunch (free time). We can enjoy some typical local dishes such as \\\"La Ruta del Pisco\\\", duck rice, sopa seca, ceviche, and other specialties\"}},{\"@type\":\"ListItem\",\"position\":5,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Winery visit and tasting\",\"description\":\"Bodega Nieto) — we will tour the winery to learn about the production of fine pisco, followed by a tasting of wines, pisco creams, macerados, and pisco, all already included in our service. Those who wish may purchase additional items\"}},{\"@type\":\"ListItem\",\"position\":6,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Visit to the Huacachina Oasis and Dunes\",\"description\":\"we will discover the thrill of Huacachina! A one-of-a-kind experience at the largest oasis in South America\"}},{\"@type\":\"ListItem\",\"position\":7,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Buggies in the desert\",\"description\":\"We will experience the excitement of riding the dunes in our off-road vehicles, driven by expert drivers who will take you across the sand dunes at full speed to enjoy breathtaking panoramic views.\"}},{\"@type\":\"ListItem\",\"position\":8,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Sandboarding\",\"description\":\"We will conquer the dunes with our sandboarding equipment and glide down the slopes on a board specially designed for sand — an exhilarating experience you simply cannot miss.\"}},{\"@type\":\"ListItem\",\"position\":9,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Return to Lima\"}},{\"@type\":\"ListItem\",\"position\":10,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Arrival at your\",\"description\":\"Arrival at your hotel\"}}]},\"offers\":{\"@type\":\"Offer\",\"price\":60,\"priceCurrency\":\"USD\",\"availability\":\"https://schema.org/InStock\",\"url\":\"https://www.limaviewtours.com/en/tours/detalle/tour-de-dia-completo-al-oasis-de-huacachina-islas-ballestas-en-paracas-2\",\"priceValidUntil\":\"2027-09-01\",\"validFrom\":\"2025-10-16\"}}' WHERE slug='tour-de-dia-completo-al-oasis-de-huacachina-islas-ballestas-en-paracas-2';
UPDATE tours SET schema_jsonld_pt='{\"@context\":\"https://schema.org\",\"@type\":[\"Product\",\"TouristTrip\"],\"@id\":\"https://www.limaviewtours.com/pt/tours/detalle/tour-de-dia-completo-al-oasis-de-huacachina-islas-ballestas-en-paracas-2#tour\",\"name\":\"TOUR DE DIA COMPLETO AO OÁSIS DE HUACACHINA + ILHAS BALLESTAS EM PARACAS\",\"description\":\"Te llevaremos a Huacachina para que explores sus impresionantes dunas de arena, disfrutes de un emocionante paseo en buggy por sus empinadas laderas y experimentes la emoción del sandboarding. Con su combinación única de adrenalina y belleza natural, huacachina ofrece una experiencia inolvidable en...\",\"url\":\"https://www.limaviewtours.com/pt/tours/detalle/tour-de-dia-completo-al-oasis-de-huacachina-islas-ballestas-en-paracas-2\",\"image\":[\"https://www.limaviewtours.com/storage/tours/gallery/01kwf99t1cnk316xa1bd53yr61.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwf8m1e0hkdzsszfcpc4tqdb.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwf8kvhv29tvz47mx6gd3psz.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwf8kx7we469vgmnxgw903re.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwf8kxxj6c359q43hd78e1z0.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwf8m08203nr083tga34mf50.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwf8kyx5rngvf2fgh3051my6.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwf8kvadre6fkq85pf077b83.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwf8kvrcfx8agpgkm2m655te.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwf8kvzpy8t99v5rhzrwb8k9.webp\"],\"inLanguage\":\"pt\",\"touristType\":[\"Sightseeing\",\"Cultural tourism\",\"Adventure\"],\"provider\":{\"@type\":\"TravelAgency\",\"name\":\"Lima View Tours\",\"url\":\"https://www.limaviewtours.com\",\"logo\":\"https://www.limaviewtours.com/assets/logos/logo.png\",\"telephone\":\"+51 925 886 725\"},\"aggregateRating\":{\"@type\":\"AggregateRating\",\"ratingValue\":5,\"reviewCount\":\"55\",\"bestRating\":5,\"worstRating\":1},\"review\":[{\"@type\":\"Review\",\"author\":{\"@type\":\"Person\",\"name\":\"Dayanne Herrera villanueva\"},\"datePublished\":\"2026-07-01\",\"reviewRating\":{\"@type\":\"Rating\",\"ratingValue\":5,\"bestRating\":5},\"reviewBody\":\"Excelente servicio. Fueron muy puntuales para nuestro tour a Islas Ballestas y Huacachina. Posteriormente les solicité información y apoyo para organizar tours en Cusco, y nuevamente recibí una atención excelente.\\n\\nTodo se manejó con gran profesionalismo, los horarios se respetaron en todo momento y los guías siempre fueron muy amables y atentos. Sin duda recomiendo esta agencia por su excelente organización y servicio al cliente.\"},{\"@type\":\"Review\",\"author\":{\"@type\":\"Person\",\"name\":\"Walter Cuadra \"},\"datePublished\":\"2026-06-27\",\"reviewRating\":{\"@type\":\"Rating\",\"ratingValue\":5,\"bestRating\":5},\"reviewBody\":\"Fizemos o passeio de Paracas + Huacachina com a agencia, e foi tudo certo, o guia era ótimo, o almoço incluso também. O passeio é maravilhoso\"},{\"@type\":\"Review\",\"author\":{\"@type\":\"Person\",\"name\":\"yinet santos alcantara\"},\"datePublished\":\"2026-06-26\",\"reviewRating\":{\"@type\":\"Rating\",\"ratingValue\":5,\"bestRating\":5},\"reviewBody\":\"⭐️⭐️⭐️⭐️⭐️ “Una experiencia inolvidable en Huacachina”\\nDesde el primer momento el trato fue excelente. El equipo fue muy amable, puntual y siempre atento a cada detalle. Nos explicaron todo con paciencia y buena vibra, haciendo que el tour fuera muy divertido y seguro. El paseo en los buggies por las dunas fue increíble, y el sandboard una experiencia única. Además, se nota que se preocupan por el bienestar del grupo y porque todos disfruten. ¡Definitivamente lo recomiendo al 100%! Fue uno...\"}],\"itinerary\":{\"@type\":\"ItemList\",\"itemListElement\":[{\"@type\":\"ListItem\",\"position\":1,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Busca no hotel\"}},{\"@type\":\"ListItem\",\"position\":2,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Faremos uma breve parada para tomar café\",\"description\":\"Faremos uma breve parada para tomar café da manhã\"}},{\"@type\":\"ListItem\",\"position\":3,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Ilhas Ballestas\",\"description\":\"chegada ao píer turístico, onde iniciaremos nossa excursão às Ilhas Ballestas. Neste percurso faremos um passeio de lancha, onde poderão admirar El Candelabro, um geoglifo de grandes dimensões muito semelhante às Linhas de Nazca. Essas ilhas são formadas naturalmente por formações rochosas que abrigam uma importante fauna marinha, com grandes colônias de aves guaneiras (Guanay, Piquero, Pelicano, Cormorão, Gaivota-de-inca, etc.). Também poderemos avistar leões-marinhos, pinguins de Humboldt e, com um pouco de sorte, golfinhos\"}},{\"@type\":\"ListItem\",\"position\":4,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Almoço\",\"description\":\"chegamos a Ica para almoçar (tempo livre). Poderemos desfrutar de alguns pratos típicos como \\\"La Ruta del Pisco\\\", arroz com pato, sopa seca, ceviche e outras especialidades\"}},{\"@type\":\"ListItem\",\"position\":5,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Visita à vitivinícola e degustação\",\"description\":\"Bodega Nieto) — faremos um tour pela adega para conhecer a elaboração de um bom pisco, seguido de degustação de vinhos, cremes de pisco, macerados e pisco, tudo já incluído no serviço. Quem desejar poderá comprar\"}},{\"@type\":\"ListItem\",\"position\":6,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Visita ao Oásis Huacachina e Dunas\",\"description\":\"vamos descobrir a emoção de Huacachina! Uma experiência única no maior oásis da América do Sul\"}},{\"@type\":\"ListItem\",\"position\":7,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Buggies no deserto\",\"description\":\"Viveremos a emoção de percorrer as dunas em nossos veículos off-road, conduzidos por motoristas experientes que levarão você pelas dunas de areia em alta velocidade para desfrutar de vistas panorâmicas deslumbrantes.\"}},{\"@type\":\"ListItem\",\"position\":8,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Sandboarding\",\"description\":\"Dominaremos as dunas com nosso equipamento de sandboarding e desceremos pelas encostas em uma prancha especialmente projetada para a areia — sem dúvida uma experiência emocionante que você não pode perder.\"}},{\"@type\":\"ListItem\",\"position\":9,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Retorno a Lima\"}},{\"@type\":\"ListItem\",\"position\":10,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Chegada ao seu hotel\"}}]},\"offers\":{\"@type\":\"Offer\",\"price\":60,\"priceCurrency\":\"USD\",\"availability\":\"https://schema.org/InStock\",\"url\":\"https://www.limaviewtours.com/pt/tours/detalle/tour-de-dia-completo-al-oasis-de-huacachina-islas-ballestas-en-paracas-2\",\"priceValidUntil\":\"2027-09-01\",\"validFrom\":\"2025-10-16\"}}' WHERE slug='tour-de-dia-completo-al-oasis-de-huacachina-islas-ballestas-en-paracas-2';
UPDATE tours SET schema_jsonld_es='{\"@context\":\"https://schema.org\",\"@type\":[\"Product\",\"TouristTrip\"],\"@id\":\"https://www.limaviewtours.com/es/tours/detalle/city-tour-en-lima-con-visita-a-las-catacumbas#tour\",\"name\":\"City Tour en Lima con visita a las Catacumbas, Centro Histórico y recojo a hotel\",\"description\":\"Iniciamos nuestra aventura recogiendo a cada pasajero desde su hotel o airbnb a las 9:00 am o a las 14:00 horas. Un día antes de la aventura, te confirmaremos  la hora exacta de recogida según la ubicación de tu alojamiento. ¡Prepárate para vivir una experiencia inolvidable en lima!“\\n\\nDescubre la ri...\",\"url\":\"https://www.limaviewtours.com/es/tours/detalle/city-tour-en-lima-con-visita-a-las-catacumbas\",\"image\":[\"https://www.limaviewtours.com/storage/tours/gallery/01kwg0d4stn0zm5db0468ty7yy.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwg0d4w974cx3kqryqhee5wm.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwg0d56f4bbajf7z6rt37n4m.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwg0d68cy3ft93qnnm9qtwq6.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwg0d6a4k3j9x7xtvg2pms14.webp\"],\"inLanguage\":\"es\",\"touristType\":[\"Sightseeing\",\"Cultural tourism\",\"Adventure\"],\"provider\":{\"@type\":\"TravelAgency\",\"name\":\"Lima View Tours\",\"url\":\"https://www.limaviewtours.com\",\"logo\":\"https://www.limaviewtours.com/assets/logos/logo.png\",\"telephone\":\"+51 925 886 725\"},\"aggregateRating\":{\"@type\":\"AggregateRating\",\"ratingValue\":5,\"reviewCount\":\"33\",\"bestRating\":5,\"worstRating\":1},\"review\":[{\"@type\":\"Review\",\"author\":{\"@type\":\"Person\",\"name\":\"Ji hank\"},\"datePublished\":\"2026-07-21\",\"reviewRating\":{\"@type\":\"Rating\",\"ratingValue\":5,\"bestRating\":5},\"reviewBody\":\"Todo excelente el guía muy bueno con mucha información\"}],\"itinerary\":{\"@type\":\"ItemList\",\"itemListElement\":[{\"@type\":\"ListItem\",\"position\":1,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"1.Parque del Amor:\",\"description\":\"Visitaremos el Parque del Amor inaugurado en 1993, el Parque del Amor es un espacio público ubicado en el distrito de Miraflores. Su principal atracción es la escultura \\\"El Beso\\\", creada por el artista peruano Victor Delfín. El parque ofrece hermosas vistas del océano pacífico y es un lugar popular para parejas y turistas.\"}},{\"@type\":\"ListItem\",\"position\":2,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"2.Huaca Pucllana( visita panoramica):\",\"description\":\"Esta pirámide preincaica fue construida por la Cultura Lima entre los siglos IV y VII d.C. Se utilizaba como centro ceremonial y administrativo. Hoy en día, Huaca Pucllana es uno de los principales sitios arqueológicos de Lima y ofrece a los visitantes una visión fascinante de la historia antigua de la ciudad.\"}},{\"@type\":\"ListItem\",\"position\":3,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"3.Plaza San Martín:\",\"description\":\"Esta plaza, ubicada en el centro histórico de Lima, conmemora la independencia de Perú y está dedicada al libertador josé de San Martín. En el centro de la plaza se encuentra una estatua ecuestre de San Martín. La plaza está rodeada por edificios históricos como el primer hotel de lujo de nuestra capital, el Hotel Bolívar, y el imponente, pero en desuso, Teatro Colón. Dos construcciones que nos recuerdan el esplendor de la Lima de antaño.El Gran Hotel Bolívar, un hotel emblemático de Lima que ha sido testigo de importantes eventos históricos y culturales. También podremos admirar el club nacional, un edificio de estilo neoclásico que alberga un club social y cultural la plaza cuenta con un paseo peatonal que nos permitira disfrutar de un agradable paseo mientras admiramos la arquitectura colonial y republicana de los edificios que la rodean\\r\\n\\r\\nNuestra próxima parada es la iglesia de nuestra señora de la merced que data del siglo XVI. Seguidamente nos dirigiremos a la Plaza de Armas de Lima\"}},{\"@type\":\"ListItem\",\"position\":4,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"4.Plaza de armas de lima:\",\"description\":\"También conocida como Plaza Mayor, es el corazón histórico y político de Lima. Fue fundada por Francisco Pizarro en 1535 y ha sido el centro de la vida pública de la ciudad desde entonces. En la plaza se encuentran la Catedral de Lima, el Palacio Arzobispal, el Palacio de Gobierno , el Palacio Municipal es aquí donde podremos visualizar una combinación de monumentos históricos y casas coloniales con balcones, que son características distintivas de la arquitectura colonial peruana. Los balcones en las casas coloniales son elementos arquitectónicos que se destacan por su belleza y estilo estos balcones suelen estar adornados con detalles tallados en madera y hierro forjado, y son un elemento característico de la arquitectura colonial en Perú.\"}},{\"@type\":\"ListItem\",\"position\":5,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"5.Banco de reserva del perú:\",\"description\":\"Fundado en 1922, es el Banco Central de Perú y se encarga de regular la moneda y el crédito en el país. El edificio del banco de reserva es una obra arquitectónica destacada de Lima y alberga una importante colección de arte y un museo donde apreciaremos la colección de tesoros del Perú dentro de los cuales hallaremos objetos de cerámica, de oro y textiles de diversas culturas pre-colombinas.\"}},{\"@type\":\"ListItem\",\"position\":6,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"6.Iglesia San Francisco y sus Catacumbas:\",\"description\":\"Otro de los lugares que visitaremos en lima que más te impresionara será la Iglesia de San Francisco este es uno de los complejos arquitectónicos más importantes de Lima y una de las iglesias más representativas del estilo barroco en América del Sur. Construida en el siglo XVII, esta iglesia es conocida por su impresionante fachada y su rica decoración interior que está decorado con obras de arte religiosos de gran valor, incluyendo pinturas, esculturas y tallas en madera. Uno de los aspectos más destacados de la iglesia es su biblioteca, que alberga una colección de libros antiguos y documentos históricos. Además de la iglesia, el complejo de San Francisco incluye un convento, un museo y las famosas Catacumbas. Las Catacumbas son un laberinto de túneles subterráneos que fueron utilizados como cementerio en la época colonial. Se estima que albergan los restos óseos de más de 70,000 personas y son un importante sitio arqueológico e histórico en lima.\"}},{\"@type\":\"ListItem\",\"position\":7,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"7.Degustacion de pisco :\",\"description\":\"Para finalizar nuestro recorrido haremos nuestra ultima parada donde nos relajaremos y podremos apreciar de ver como se prepara el pisco sour aquí tambien podremos degustar otros tipos de variaciones pisco ,cocteles y mas\"}},{\"@type\":\"ListItem\",\"position\":8,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"8.Regreso al hotel:\",\"description\":\"después de disfrutar de la belleza y la historia, regresaremos a tu hotel para concluir nuestro tour.\"}}]},\"offers\":{\"@type\":\"Offer\",\"price\":33,\"priceCurrency\":\"USD\",\"availability\":\"https://schema.org/InStock\",\"url\":\"https://www.limaviewtours.com/es/tours/detalle/city-tour-en-lima-con-visita-a-las-catacumbas\",\"priceValidUntil\":\"2027-09-01\",\"validFrom\":\"2025-10-21\"}}' WHERE slug='city-tour-en-lima-con-visita-a-las-catacumbas';
