UPDATE tours SET schema_jsonld_es='{\"@context\":\"https://schema.org\",\"@type\":[\"Product\",\"TouristTrip\"],\"@id\":\"https://www.limaviewtours.com/es/tours/detalle/tour-oasis-huacachina-picnic-atardecer-buggy#tour\",\"name\":\"Tour al Oasis Huacachina con picnic, buggy y atardecer en el desierto\",\"description\":\"Vive un full day inolvidable desde Lima hacia Paracas, Islas Ballestas y Huacachina. Disfruta la fauna marina, el oasis del desierto, buggy, sandboarding, degustación local y termina el día con un picnic al atardecer en las dunas.\",\"url\":\"https://www.limaviewtours.com/es/tours/detalle/tour-oasis-huacachina-picnic-atardecer-buggy\",\"image\":[\"https://www.limaviewtours.com/storage/tours/gallery/01kwhzfs22kka8g2vdjhnytzj9.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwhrf5fmc7p6a6nmzsn5d91j.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwn5c6vyz0rqk6gc0mcqw35f.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwn5c7023253emm67yzem6f7.webp\"],\"inLanguage\":\"es\",\"touristType\":[\"Sightseeing\",\"Cultural tourism\",\"Adventure\"],\"provider\":{\"@type\":\"TravelAgency\",\"name\":\"Lima View Tours\",\"url\":\"https://www.limaviewtours.com\",\"logo\":\"https://www.limaviewtours.com/assets/logos/logo.png\",\"telephone\":\"+51 925 886 725\"},\"aggregateRating\":{\"@type\":\"AggregateRating\",\"ratingValue\":5,\"reviewCount\":\"12\",\"bestRating\":5,\"worstRating\":1},\"itinerary\":{\"@type\":\"ItemList\",\"itemListElement\":[{\"@type\":\"ListItem\",\"position\":1,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Recojo a Hotel\",\"description\":\"Recojo desde tu hotel o punto de encuentro. El horario exacto de recojo se lo enviaremos un dia antes del tour.\"}},{\"@type\":\"ListItem\",\"position\":2,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Parada para desayuno\",\"description\":\"Parada en ruta para que los pasajeros puedan desayunar.\"}},{\"@type\":\"ListItem\",\"position\":3,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Tour a Islas Ballestas\",\"description\":\"Llegada a Paracas para abordar la embarcación hacia las Islas Ballestas. Durante el recorrido se podrán observar paisajes marinos, aves, lobos marinos y el famoso Candelabro. duración 1 hora con 30 minutos aproximadamente.\"}},{\"@type\":\"ListItem\",\"position\":4,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Degustación de pisco\",\"description\":\"Visita a una bodega local para conocer parte de la tradición vitivinícola de Ica y realizar una degustación de los licores típicos de la zona.\"}},{\"@type\":\"ListItem\",\"position\":5,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Almuerzo\",\"description\":\"Tiempo para almorzar en restaurante local.\\n\\\"Almuerzo no incluido en el precio\\\"\"}},{\"@type\":\"ListItem\",\"position\":6,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Visita al Oasis de Huacachina\",\"description\":\"Llegada al oasis de Huacachina. Tiempo para caminar, tomar fotos y disfrutar la vista del oasis rodeado de dunas.\"}},{\"@type\":\"ListItem\",\"position\":7,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Buggy y sandboarding\",\"description\":\"Aventura en buggy por las dunas de Huacachina y práctica de sandboarding en el desierto.\"}},{\"@type\":\"ListItem\",\"position\":8,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Atardecer y picnic en el desierto\",\"description\":\"Disfruta un picnic sencillo y especial en las dunas, con mantas, cojines, mesa baja, bebidas y snacks ligeros mientras cae el atardecer.\"}},{\"@type\":\"ListItem\",\"position\":9,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Retorno a Lima\",\"description\":\"Salida desde Huacachina hacia Lima.\\nLlegada aproximada a Lima entre 10:30 p. m. y 11:30 p. m.\"}}]},\"offers\":{\"@type\":\"Offer\",\"price\":100,\"priceCurrency\":\"USD\",\"availability\":\"https://schema.org/InStock\",\"url\":\"https://www.limaviewtours.com/es/tours/detalle/tour-oasis-huacachina-picnic-atardecer-buggy\",\"priceValidUntil\":\"2027-09-01\",\"validFrom\":\"2026-07-02\"}}' WHERE slug='tour-oasis-huacachina-picnic-atardecer-buggy';
UPDATE tours SET schema_jsonld_en='{\"@context\":\"https://schema.org\",\"@type\":[\"Product\",\"TouristTrip\"],\"@id\":\"https://www.limaviewtours.com/en/tours/detalle/tour-oasis-huacachina-picnic-atardecer-buggy#tour\",\"name\":\"Tour al Oasis Huacachina con picnic, buggy y atardecer en el desierto\",\"description\":\"Vive un full day inolvidable desde Lima hacia Paracas, Islas Ballestas y Huacachina. Disfruta la fauna marina, el oasis del desierto, buggy, sandboarding, degustación local y termina el día con un picnic al atardecer en las dunas.\",\"url\":\"https://www.limaviewtours.com/en/tours/detalle/tour-oasis-huacachina-picnic-atardecer-buggy\",\"image\":[\"https://www.limaviewtours.com/storage/tours/gallery/01kwhzfs22kka8g2vdjhnytzj9.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwhrf5fmc7p6a6nmzsn5d91j.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwn5c6vyz0rqk6gc0mcqw35f.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwn5c7023253emm67yzem6f7.webp\"],\"inLanguage\":\"en\",\"touristType\":[\"Sightseeing\",\"Cultural tourism\",\"Adventure\"],\"provider\":{\"@type\":\"TravelAgency\",\"name\":\"Lima View Tours\",\"url\":\"https://www.limaviewtours.com\",\"logo\":\"https://www.limaviewtours.com/assets/logos/logo.png\",\"telephone\":\"+51 925 886 725\"},\"aggregateRating\":{\"@type\":\"AggregateRating\",\"ratingValue\":5,\"reviewCount\":\"12\",\"bestRating\":5,\"worstRating\":1},\"offers\":{\"@type\":\"Offer\",\"price\":100,\"priceCurrency\":\"USD\",\"availability\":\"https://schema.org/InStock\",\"url\":\"https://www.limaviewtours.com/en/tours/detalle/tour-oasis-huacachina-picnic-atardecer-buggy\",\"priceValidUntil\":\"2027-09-01\",\"validFrom\":\"2026-07-02\"}}' WHERE slug='tour-oasis-huacachina-picnic-atardecer-buggy';
