UPDATE tours SET schema_jsonld_es='{\"@context\":\"https://schema.org\",\"@type\":[\"Product\",\"TouristTrip\"],\"@id\":\"https://www.limaviewtours.com/es/tours/detalle/centro-historico-de-lima-parque-de-las-aguas#tour\",\"name\":\"CITY TOUR POR LA TARDE + PARQUE DE LAS AGUAS\",\"description\":\"Disfruta de una experiencia única explorando el centro histórico de Lima de noche, donde podrás admirar la majestuosidad de la Plaza Mayor, la imponente Catedral de Lima, el Palacio de Gobierno y el Convento de San Francisco. Luego, sumérgete en un espectáculo de luces y agua en el Parque de las Agu...\",\"url\":\"https://www.limaviewtours.com/es/tours/detalle/centro-historico-de-lima-parque-de-las-aguas\",\"image\":[\"https://www.limaviewtours.com/storage/tours/covers/01KWDEEBJHMQ096NQJ15CTVTBK.avif\"],\"inLanguage\":\"es\",\"touristType\":[\"Sightseeing\",\"Cultural tourism\",\"Adventure\"],\"provider\":{\"@type\":\"TravelAgency\",\"name\":\"Lima View Tours\",\"url\":\"https://www.limaviewtours.com\",\"logo\":\"https://www.limaviewtours.com/assets/logos/logo.png\",\"telephone\":\"+51 925 886 725\"},\"aggregateRating\":{\"@type\":\"AggregateRating\",\"ratingValue\":5,\"reviewCount\":\"20\",\"bestRating\":5,\"worstRating\":1},\"itinerary\":{\"@type\":\"ItemList\",\"itemListElement\":[{\"@type\":\"ListItem\",\"position\":1,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Inicio en el hotel\",\"description\":\"Nos encontraremos en el lobby de tu hotel para iniciar nuestro recorrido por el centro histórico de Lima y el Parque de las Aguas.\"}},{\"@type\":\"ListItem\",\"position\":2,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Centro Histórico de Lima de noche\"}},{\"@type\":\"ListItem\",\"position\":3,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Plaza Mayor\",\"description\":\"Nuestra primera parada será en la Plaza Mayor, donde podremos apreciar la majestuosa arquitectura colonial iluminada y disfrutar de la atmósfera nocturna de este importante espacio histórico.\"}},{\"@type\":\"ListItem\",\"position\":4,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Monumentos Históricos\",\"description\":\"Visualizaremos algunos monumentos y casa con balcones coloniales republicanos etc.\"}},{\"@type\":\"ListItem\",\"position\":5,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Catedral de Lima\",\"description\":\"Visitaremos La Catedral de Lima, una de las principales iglesias de la ciudad que destaca por su belleza arquitectónica y su historia.\"}},{\"@type\":\"ListItem\",\"position\":6,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Palacio de Gobierno\",\"description\":\"continuaremos nuestro recorrido hacia el palacio de gobierno, donde podremos ver el cambio de guardia, una ceremonia tradicional que se realiza todas las noches.\"}},{\"@type\":\"ListItem\",\"position\":7,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Convento de San Francisco\",\"description\":\"Concluiremos nuestro recorrido por el centro histórico en el convento de san francisco, donde podremos explorar sus catacumbas y conocer más sobre la historia colonial de Lima.\"}},{\"@type\":\"ListItem\",\"position\":8,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Parque de las Aguas\",\"description\":\"Espectáculo de luces y agua después de disfrutar del centro histórico, nos dirigiremos al parque de las aguas para disfrutar de su espectáculo de luces y agua, donde podremos ver las fuentes iluminadas y sincronizadas con música en un espectáculo único.\"}},{\"@type\":\"ListItem\",\"position\":9,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Regreso al hotel\",\"description\":\"después de disfrutar de la belleza y la historia del centro histórico de Lima y el Parque de las Aguas, regresaremos a tu hotel para concluir nuestro tour.\"}}]},\"offers\":{\"@type\":\"Offer\",\"price\":150,\"priceCurrency\":\"USD\",\"availability\":\"https://schema.org/InStock\",\"url\":\"https://www.limaviewtours.com/es/tours/detalle/centro-historico-de-lima-parque-de-las-aguas\",\"priceValidUntil\":\"2027-09-01\",\"validFrom\":\"2025-10-21\"}}' WHERE slug='centro-historico-de-lima-parque-de-las-aguas';
UPDATE tours SET schema_jsonld_en='{\"@context\":\"https://schema.org\",\"@type\":[\"Product\",\"TouristTrip\"],\"@id\":\"https://www.limaviewtours.com/en/tours/detalle/centro-historico-de-lima-parque-de-las-aguas#tour\",\"name\":\"AFTERNOON CITY TOUR + MAGIC WATER CIRCUIT\",\"description\":\"Disfruta de una experiencia única explorando el centro histórico de Lima de noche, donde podrás admirar la majestuosidad de la Plaza Mayor, la imponente Catedral de Lima, el Palacio de Gobierno y el Convento de San Francisco. Luego, sumérgete en un espectáculo de luces y agua en el Parque de las Agu...\",\"url\":\"https://www.limaviewtours.com/en/tours/detalle/centro-historico-de-lima-parque-de-las-aguas\",\"image\":[\"https://www.limaviewtours.com/storage/tours/covers/01KWDEEBJHMQ096NQJ15CTVTBK.avif\"],\"inLanguage\":\"en\",\"touristType\":[\"Sightseeing\",\"Cultural tourism\",\"Adventure\"],\"provider\":{\"@type\":\"TravelAgency\",\"name\":\"Lima View Tours\",\"url\":\"https://www.limaviewtours.com\",\"logo\":\"https://www.limaviewtours.com/assets/logos/logo.png\",\"telephone\":\"+51 925 886 725\"},\"aggregateRating\":{\"@type\":\"AggregateRating\",\"ratingValue\":5,\"reviewCount\":\"20\",\"bestRating\":5,\"worstRating\":1},\"itinerary\":{\"@type\":\"ItemList\",\"itemListElement\":[{\"@type\":\"ListItem\",\"position\":1,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Inicio en el hotel\",\"description\":\"We will meet in your hotel lobby to begin our tour of Lima\'s historic center and the Parque de las Aguas.\"}},{\"@type\":\"ListItem\",\"position\":2,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Centro Histórico de Lima de noche\"}},{\"@type\":\"ListItem\",\"position\":3,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Plaza Mayor\",\"description\":\"Our first stop will be the Plaza Mayor, where we can admire the majestic illuminated colonial architecture and enjoy the nighttime atmosphere of this important historic landmark.\"}},{\"@type\":\"ListItem\",\"position\":4,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Monumentos Históricos\",\"description\":\"We will view various monuments and colonial republican-style houses with balconies, etc.\"}},{\"@type\":\"ListItem\",\"position\":5,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Catedral de Lima\",\"description\":\"We will visit the Lima Cathedral, one of the city\'s main churches, renowned for its architectural beauty and rich history.\"}},{\"@type\":\"ListItem\",\"position\":6,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Palacio de Gobierno\",\"description\":\"We will continue our tour to the Government Palace, where we can watch the changing of the guard, a traditional ceremony held every evening.\"}},{\"@type\":\"ListItem\",\"position\":7,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Convento de San Francisco\",\"description\":\"We will conclude our tour of the historic center at the Convent of San Francisco, where we can explore its catacombs and learn more about Lima\'s colonial history.\"}},{\"@type\":\"ListItem\",\"position\":8,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Parque de las Aguas\",\"description\":\"Light and water show — after enjoying the historic center, we will head to the Parque de las Aguas to enjoy its light and water show, where we can see the illuminated fountains synchronized with music in a one-of-a-kind spectacle.\"}},{\"@type\":\"ListItem\",\"position\":9,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Regreso al hotel\",\"description\":\"After enjoying the beauty and history of Lima\'s historic center and the Parque de las Aguas, we will return to your hotel to conclude our tour.\"}}]},\"offers\":{\"@type\":\"Offer\",\"price\":150,\"priceCurrency\":\"USD\",\"availability\":\"https://schema.org/InStock\",\"url\":\"https://www.limaviewtours.com/en/tours/detalle/centro-historico-de-lima-parque-de-las-aguas\",\"priceValidUntil\":\"2027-09-01\",\"validFrom\":\"2025-10-21\"}}' WHERE slug='centro-historico-de-lima-parque-de-las-aguas';
UPDATE tours SET schema_jsonld_pt='{\"@context\":\"https://schema.org\",\"@type\":[\"Product\",\"TouristTrip\"],\"@id\":\"https://www.limaviewtours.com/pt/tours/detalle/centro-historico-de-lima-parque-de-las-aguas#tour\",\"name\":\"CITY TOUR À TARDE + PARQUE DAS ÁGUAS\",\"description\":\"Disfruta de una experiencia única explorando el centro histórico de Lima de noche, donde podrás admirar la majestuosidad de la Plaza Mayor, la imponente Catedral de Lima, el Palacio de Gobierno y el Convento de San Francisco. Luego, sumérgete en un espectáculo de luces y agua en el Parque de las Agu...\",\"url\":\"https://www.limaviewtours.com/pt/tours/detalle/centro-historico-de-lima-parque-de-las-aguas\",\"image\":[\"https://www.limaviewtours.com/storage/tours/covers/01KWDEEBJHMQ096NQJ15CTVTBK.avif\"],\"inLanguage\":\"pt\",\"touristType\":[\"Sightseeing\",\"Cultural tourism\",\"Adventure\"],\"provider\":{\"@type\":\"TravelAgency\",\"name\":\"Lima View Tours\",\"url\":\"https://www.limaviewtours.com\",\"logo\":\"https://www.limaviewtours.com/assets/logos/logo.png\",\"telephone\":\"+51 925 886 725\"},\"aggregateRating\":{\"@type\":\"AggregateRating\",\"ratingValue\":5,\"reviewCount\":\"20\",\"bestRating\":5,\"worstRating\":1},\"itinerary\":{\"@type\":\"ItemList\",\"itemListElement\":[{\"@type\":\"ListItem\",\"position\":1,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Inicio en el hotel\",\"description\":\"Nos encontraremos no lobby do seu hotel para iniciar nosso passeio pelo centro histórico de Lima e o Parque das Águas.\"}},{\"@type\":\"ListItem\",\"position\":2,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Centro Histórico de Lima de noche\"}},{\"@type\":\"ListItem\",\"position\":3,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Plaza Mayor\",\"description\":\"Nossa primeira parada será na Plaza Mayor, onde poderemos admirar a majestosa arquitetura colonial iluminada e aproveitar a atmosfera noturna deste importante espaço histórico.\"}},{\"@type\":\"ListItem\",\"position\":4,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Monumentos Históricos\",\"description\":\"Visualizaremos alguns monumentos e casas com varandas coloniais republicanas, etc.\"}},{\"@type\":\"ListItem\",\"position\":5,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Catedral de Lima\",\"description\":\"Visitaremos a Catedral de Lima, uma das principais igrejas da cidade, destacada por sua beleza arquitetônica e sua história.\"}},{\"@type\":\"ListItem\",\"position\":6,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Palacio de Gobierno\",\"description\":\"Continuaremos nosso passeio em direção ao Palácio do Governo, onde poderemos assistir à troca da guarda, uma cerimônia tradicional realizada todas as noites.\"}},{\"@type\":\"ListItem\",\"position\":7,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Convento de San Francisco\",\"description\":\"Concluiremos nosso passeio pelo centro histórico no Convento de San Francisco, onde poderemos explorar suas catacumbas e conhecer mais sobre a história colonial de Lima.\"}},{\"@type\":\"ListItem\",\"position\":8,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Parque de las Aguas\",\"description\":\"Espetáculo de luzes e água — após desfrutar do centro histórico, nos dirigiremos ao Parque das Águas para aproveitar seu espetáculo de luzes e água, onde poderemos ver as fontes iluminadas e sincronizadas com música em um espetáculo único.\"}},{\"@type\":\"ListItem\",\"position\":9,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Regreso al hotel\",\"description\":\"Após desfrutar da beleza e da história do centro histórico de Lima e do Parque das Águas, retornaremos ao seu hotel para concluir nosso tour.\"}}]},\"offers\":{\"@type\":\"Offer\",\"price\":150,\"priceCurrency\":\"USD\",\"availability\":\"https://schema.org/InStock\",\"url\":\"https://www.limaviewtours.com/pt/tours/detalle/centro-historico-de-lima-parque-de-las-aguas\",\"priceValidUntil\":\"2027-09-01\",\"validFrom\":\"2025-10-21\"}}' WHERE slug='centro-historico-de-lima-parque-de-las-aguas';
UPDATE tours SET schema_jsonld_es='{\"@context\":\"https://schema.org\",\"@type\":[\"Product\",\"TouristTrip\"],\"@id\":\"https://www.limaviewtours.com/es/tours/detalle/tour-privado-huacachina-islas-ballestas-atardecer-buggy-can-am#tour\",\"name\":\"Tour privado a Huacachina, Paracas e Islas Ballestas con buggy Can-Am y atardecer en el desierto\",\"description\":\"Te llevaremos a Huacachina en un tour privado para que explores sus impresionantes dunas de arena, disfrutes de un emocionante paseo en buggy (canam) por sus empinadas laderas y experimentes la emoción del sandboarding. Con su combinación única de adrenalina y belleza natural, Huacachina ofrece una...\",\"url\":\"https://www.limaviewtours.com/es/tours/detalle/tour-privado-huacachina-islas-ballestas-atardecer-buggy-can-am\",\"image\":[\"https://www.limaviewtours.com/storage/tours/gallery/01kwfdj1j008tz4tbcdjt7hevg.webp\",\"https://www.limaviewtours.com/storage/tours/OASIS-DE-HUACACHINA-CON-BUGGIE-4.jpg\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwfdj1brrpwfawp1m8ke4770.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwfdhzyeh7x633v46fy7bqbh.webp\",\"https://www.limaviewtours.com/storage/tours/OASIS-DE-HUACACHINA-CON-BUGGIE-3.jpg\",\"https://www.limaviewtours.com/storage/tours/OASIS-DE-HUACACHINA-CON-BUGGIE-7-scaled-1.jpg\",\"https://www.limaviewtours.com/storage/tours/OASIS-DE-HUACACHINA-CON-BUGGIE-5.jpg\",\"https://www.limaviewtours.com/storage/tours/OASIS-DE-HUACACHINA-CON-BUGGIE-9-scaled-1.jpg\",\"https://www.limaviewtours.com/storage/tours/OASIS-DE-HUACACHINA-CON-BUGGIE-8-scaled-1.jpg\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwfdj04rb8y5cdymbedcddzv.webp\",\"https://www.limaviewtours.com/storage/tours/OASIS-DE-HUACACHINA-CON-BUGGIE-12.jpg\",\"https://www.limaviewtours.com/storage/tours/OASIS-DE-HUACACHINA-CON-BUGGIE-11.jpg\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwfdj0gjptpnwk7rr1ds8r5a.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwfdj0ypanxdke5jbaqqytng.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwfdj1633xcmm6xx7k0g9zfg.webp\",\"https://www.limaviewtours.com/storage/tours/OASIS-DE-HUACACHINA-CON-BUGGIE-10-scaled-1.jpg\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwfdhzpyxhx4jj1pkaxpkphq.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwfdj1rkm3gsakje1fy76kpq.webp\",\"https://www.limaviewtours.com/storage/tours/OASIS-DE-HUACACHINA-CON-BUGGIE-2.jpg\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwfdj0qnxkrk2y60w20qq4pn.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwfdj1zjb2jkaj1zm5f6q5br.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwfdj0ah2ezzd7cm29jqzqmm.webp\",\"https://www.limaviewtours.com/storage/tours/OASIS-DE-HUACACHINA-CON-BUGGIE-6-scaled-1.jpg\"],\"inLanguage\":\"es\",\"touristType\":[\"Sightseeing\",\"Cultural tourism\",\"Adventure\"],\"provider\":{\"@type\":\"TravelAgency\",\"name\":\"Lima View Tours\",\"url\":\"https://www.limaviewtours.com\",\"logo\":\"https://www.limaviewtours.com/assets/logos/logo.png\",\"telephone\":\"+51 925 886 725\"},\"aggregateRating\":{\"@type\":\"AggregateRating\",\"ratingValue\":5,\"reviewCount\":\"20\",\"bestRating\":5,\"worstRating\":1},\"itinerary\":{\"@type\":\"ItemList\",\"itemListElement\":[{\"@type\":\"ListItem\",\"position\":1,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Lo recojeremos en su\",\"description\":\"lo recojeremos en su hotel\"}},{\"@type\":\"ListItem\",\"position\":2,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Realizaremos una breve parada para poder\",\"description\":\"realizaremos una breve parada para poder tomar desayuno\"}},{\"@type\":\"ListItem\",\"position\":3,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Islas Ballestas\",\"description\":\"llegada al muelle turístico donde iniciaremos nuestra excursión hacia las Islas Ballestas , en este recorrido haremos un paseoen el deslizador, es aquí donde podran apreciar\"}},{\"@type\":\"ListItem\",\"position\":4,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"El Candelabro\",\"description\":\"que es un geoglifo de grandes dimensiones muy similares a las Líneas de Nazca. Esta isla esta hecha naturalmente de formaciones rocosas que albergan una importante fauna marina, donde habitan grandes colonias de aves guaneras (guanay, piquero, pelÍcano, cormoran, zarcillos, etc.) Tambien podremos visualizar lobos marinos, Pingüinos de Humboldt y con un poco de suerte delfines.\"}},{\"@type\":\"ListItem\",\"position\":5,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Almuerzo\",\"description\":\"llegamos a ica para almorzar (tiempo libre), podremos disfrutar de algunos platos tipicos como “La Ruta del Pisco”, arroz con pato, sopa seca ceviche y otros platos.\"}},{\"@type\":\"ListItem\",\"position\":6,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Visita a la vitivinivola y degustación (Bodega Nietto)\",\"description\":\"haremos un recorrido hacia la bodega para poder conocer la elaboración de un buen pisco, luego pasaremos a degustar, vinos, cremas de pisco, macerados y pisco todo ya incluido en nuestro servicio, los que deseen pueden comprar.\"}},{\"@type\":\"ListItem\",\"position\":7,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Visita al Oasis Huacachina y dunas\",\"description\":\"¡Descubriremos la emoción en Huacachina! Una experiencia única en el oasis mas grande de Sudamérica.\"}},{\"@type\":\"ListItem\",\"position\":8,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Buggies en el desierto\",\"description\":\"experimentaremos la emoción de recorrer las dunas en nuestros vehículos todo terreno privado llamado (canam), conducidos por expertos choferes que te llevarán a través las dunas de arena a toda velocidad para disfrutar de vistas panorámicas impresionantes 1:00 hora de recorrido .\"}},{\"@type\":\"ListItem\",\"position\":9,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Sandboarding\",\"description\":\"dominaremos las dunas con nuestro equipo de sandboarding y nos deslízaremos por las pendientes en una tabla especialmente diseñada para la arena, sin duda es una experiencia emocionante que no te puedes perder al termino de estos deportes de aventura partiremos a Chincha.\"}},{\"@type\":\"ListItem\",\"position\":10,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Llegada a Chincha /Bodega Racimo de Uva\",\"description\":\"Chincha será nuestra última parada para degustar algunos macerados de pisco, piscos puros y podrán comprar mamajuanas, también podrán degustar algunos postres tipicos de chincha como tejas, chocotejas.\"}},{\"@type\":\"ListItem\",\"position\":11,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Retorno a Lima\"}},{\"@type\":\"ListItem\",\"position\":12,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Llegada a su hotel.\"}}]},\"offers\":{\"@type\":\"Offer\",\"price\":250,\"priceCurrency\":\"USD\",\"availability\":\"https://schema.org/InStock\",\"url\":\"https://www.limaviewtours.com/es/tours/detalle/tour-privado-huacachina-islas-ballestas-atardecer-buggy-can-am\",\"priceValidUntil\":\"2027-09-01\",\"validFrom\":\"2025-10-21\"}}' WHERE slug='tour-privado-huacachina-islas-ballestas-atardecer-buggy-can-am';
UPDATE tours SET schema_jsonld_en='{\"@context\":\"https://schema.org\",\"@type\":[\"Product\",\"TouristTrip\"],\"@id\":\"https://www.limaviewtours.com/en/tours/detalle/tour-privado-huacachina-islas-ballestas-atardecer-buggy-can-am#tour\",\"name\":\"FULL-DAY TOUR TO THE HUACACHINA OASIS WITH PRIVATE BUGGY (CANAM) + BALLESTAS ISLANDS IN PARACAS\",\"description\":\"Te llevaremos a Huacachina en un tour privado para que explores sus impresionantes dunas de arena, disfrutes de un emocionante paseo en buggy (canam) por sus empinadas laderas y experimentes la emoción del sandboarding. Con su combinación única de adrenalina y belleza natural, Huacachina ofrece una...\",\"url\":\"https://www.limaviewtours.com/en/tours/detalle/tour-privado-huacachina-islas-ballestas-atardecer-buggy-can-am\",\"image\":[\"https://www.limaviewtours.com/storage/tours/gallery/01kwfdj1j008tz4tbcdjt7hevg.webp\",\"https://www.limaviewtours.com/storage/tours/OASIS-DE-HUACACHINA-CON-BUGGIE-4.jpg\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwfdj1brrpwfawp1m8ke4770.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwfdhzyeh7x633v46fy7bqbh.webp\",\"https://www.limaviewtours.com/storage/tours/OASIS-DE-HUACACHINA-CON-BUGGIE-3.jpg\",\"https://www.limaviewtours.com/storage/tours/OASIS-DE-HUACACHINA-CON-BUGGIE-7-scaled-1.jpg\",\"https://www.limaviewtours.com/storage/tours/OASIS-DE-HUACACHINA-CON-BUGGIE-5.jpg\",\"https://www.limaviewtours.com/storage/tours/OASIS-DE-HUACACHINA-CON-BUGGIE-9-scaled-1.jpg\",\"https://www.limaviewtours.com/storage/tours/OASIS-DE-HUACACHINA-CON-BUGGIE-8-scaled-1.jpg\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwfdj04rb8y5cdymbedcddzv.webp\",\"https://www.limaviewtours.com/storage/tours/OASIS-DE-HUACACHINA-CON-BUGGIE-12.jpg\",\"https://www.limaviewtours.com/storage/tours/OASIS-DE-HUACACHINA-CON-BUGGIE-11.jpg\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwfdj0gjptpnwk7rr1ds8r5a.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwfdj0ypanxdke5jbaqqytng.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwfdj1633xcmm6xx7k0g9zfg.webp\",\"https://www.limaviewtours.com/storage/tours/OASIS-DE-HUACACHINA-CON-BUGGIE-10-scaled-1.jpg\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwfdhzpyxhx4jj1pkaxpkphq.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwfdj1rkm3gsakje1fy76kpq.webp\",\"https://www.limaviewtours.com/storage/tours/OASIS-DE-HUACACHINA-CON-BUGGIE-2.jpg\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwfdj0qnxkrk2y60w20qq4pn.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwfdj1zjb2jkaj1zm5f6q5br.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwfdj0ah2ezzd7cm29jqzqmm.webp\",\"https://www.limaviewtours.com/storage/tours/OASIS-DE-HUACACHINA-CON-BUGGIE-6-scaled-1.jpg\"],\"inLanguage\":\"en\",\"touristType\":[\"Sightseeing\",\"Cultural tourism\",\"Adventure\"],\"provider\":{\"@type\":\"TravelAgency\",\"name\":\"Lima View Tours\",\"url\":\"https://www.limaviewtours.com\",\"logo\":\"https://www.limaviewtours.com/assets/logos/logo.png\",\"telephone\":\"+51 925 886 725\"},\"aggregateRating\":{\"@type\":\"AggregateRating\",\"ratingValue\":5,\"reviewCount\":\"20\",\"bestRating\":5,\"worstRating\":1},\"itinerary\":{\"@type\":\"ItemList\",\"itemListElement\":[{\"@type\":\"ListItem\",\"position\":1,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"We will pick you up at your hotel\"}},{\"@type\":\"ListItem\",\"position\":2,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"We will make a brief stop for breakfast\"}},{\"@type\":\"ListItem\",\"position\":3,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Ballestas Islands\",\"description\":\"Arrival at the tourist pier where we will begin our excursion to the Ballestas Islands. During this tour we will take a boat ride where you will be able to appreciate\"}},{\"@type\":\"ListItem\",\"position\":4,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"El Candelabro\",\"description\":\"a large geoglyph very similar to the Nazca Lines. This island is naturally made of rocky formations that host important marine wildlife, including large colonies of guano birds (Guanay cormorant, Peruvian booby, Peruvian pelican, cormorant, Inca tern, etc.). We will also be able to spot sea lions, Humboldt penguins, and with a bit of luck, dolphins.\"}},{\"@type\":\"ListItem\",\"position\":5,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Lunch\",\"description\":\"We arrive in Ica for lunch (free time). We can enjoy some typical dishes such as \\\"La Ruta del Pisco,\\\" duck rice, sopa seca, ceviche, and other dishes.\"}},{\"@type\":\"ListItem\",\"position\":6,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Visit to the winery and tasting (Bodega Nietto)\",\"description\":\"We will take a tour of the winery to learn about the making of a great pisco, then we will taste wines, pisco creams, macerations, and pisco — all already included in our service. Those who wish may purchase.\"}},{\"@type\":\"ListItem\",\"position\":7,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Visit to the Huacachina Oasis and dunes\",\"description\":\"We will discover the thrill of Huacachina! A unique experience at the largest oasis in South America.\"}},{\"@type\":\"ListItem\",\"position\":8,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Buggies in the desert\",\"description\":\"We will experience the thrill of riding through the dunes in our private off-road vehicle (canam), driven by expert drivers who will take you across the sand dunes at full speed to enjoy breathtaking panoramic views — a 1-hour ride.\"}},{\"@type\":\"ListItem\",\"position\":9,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Sandboarding\",\"description\":\"We will conquer the dunes with our sandboarding gear, sliding down the slopes on a board specially designed for sand. It is undoubtedly an exciting experience you cannot miss. After these adventure sports we will head to Chincha.\"}},{\"@type\":\"ListItem\",\"position\":10,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Arrival in Chincha / Bodega Racimo de Uva\",\"description\":\"Chincha will be our last stop to taste some pisco macerations and pure piscos. You will also be able to purchase mamajuanas and try some typical Chincha desserts such as tejas and chocotejas.\"}},{\"@type\":\"ListItem\",\"position\":11,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Return to Lima\"}},{\"@type\":\"ListItem\",\"position\":12,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Arrival at your hotel.\"}}]},\"offers\":{\"@type\":\"Offer\",\"price\":250,\"priceCurrency\":\"USD\",\"availability\":\"https://schema.org/InStock\",\"url\":\"https://www.limaviewtours.com/en/tours/detalle/tour-privado-huacachina-islas-ballestas-atardecer-buggy-can-am\",\"priceValidUntil\":\"2027-09-01\",\"validFrom\":\"2025-10-21\"}}' WHERE slug='tour-privado-huacachina-islas-ballestas-atardecer-buggy-can-am';
