s/gallery/01kwfdj0ypanxdke5jbaqqytng.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwfdj1633xcmm6xx7k0g9zfg.webp\",\"https://www.limaviewtours.com/storage/tours/OASIS-DE-HUACACHINA-CON-BUGGIE-10-scaled-1.jpg\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwfdhzpyxhx4jj1pkaxpkphq.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwfdj1rkm3gsakje1fy76kpq.webp\",\"https://www.limaviewtours.com/storage/tours/OASIS-DE-HUACACHINA-CON-BUGGIE-2.jpg\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwfdj0qnxkrk2y60w20qq4pn.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwfdj1zjb2jkaj1zm5f6q5br.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwfdj0ah2ezzd7cm29jqzqmm.webp\",\"https://www.limaviewtours.com/storage/tours/OASIS-DE-HUACACHINA-CON-BUGGIE-6-scaled-1.jpg\"],\"inLanguage\":\"pt\",\"touristType\":[\"Sightseeing\",\"Cultural tourism\",\"Adventure\"],\"provider\":{\"@type\":\"TravelAgency\",\"name\":\"Lima View Tours\",\"url\":\"https://www.limaviewtours.com\",\"logo\":\"https://www.limaviewtours.com/assets/logos/logo.png\",\"telephone\":\"+51 925 886 725\"},\"aggregateRating\":{\"@type\":\"AggregateRating\",\"ratingValue\":5,\"reviewCount\":\"20\",\"bestRating\":5,\"worstRating\":1},\"itinerary\":{\"@type\":\"ItemList\",\"itemListElement\":[{\"@type\":\"ListItem\",\"position\":1,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Vamos buscá\",\"description\":\"lo no seu hotel\"}},{\"@type\":\"ListItem\",\"position\":2,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Faremos uma breve parada para o café da manhã\"}},{\"@type\":\"ListItem\",\"position\":3,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Ilhas Ballestas\",\"description\":\"Chegada ao cais turístico, onde iniciaremos nossa excursão às Ilhas Ballestas. Neste percurso faremos um passeio de barco, onde você poderá apreciar\"}},{\"@type\":\"ListItem\",\"position\":4,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"El Candelabro\",\"description\":\"um grande geoglifo muito semelhante às Linhas de Nazca. Esta ilha é formada naturalmente por formações rochosas que abrigam uma importante fauna marinha, onde vivem grandes colônias de aves guaneiras (cormorão de Guanay, atobá peruano, pelicano peruano, cormorão, trinta-réis inca, etc.). Também poderemos avistar lobos-marinhos, pinguins de Humboldt e, com um pouco de sorte, golfinhos.\"}},{\"@type\":\"ListItem\",\"position\":5,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Almoço\",\"description\":\"Chegamos a Ica para almoçar (tempo livre). Podemos desfrutar de alguns pratos típicos como \\\"La Ruta del Pisco\\\", arroz com pato, sopa seca, ceviche e outros pratos.\"}},{\"@type\":\"ListItem\",\"position\":6,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Visita à vinícola e degustação (Bodega Nietto)\",\"description\":\"Faremos um passeio pela bodega para conhecer a elaboração de um bom pisco e, em seguida, degustaremos vinhos, cremes de pisco, macerados e pisco — tudo já incluído no nosso serviço. Quem desejar poderá comprar.\"}},{\"@type\":\"ListItem\",\"position\":7,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Visita ao Oásis de Huacachina e dunas\",\"description\":\"Descobriremos a emoção de Huacachina! Uma experiência única no maior oásis da América do Sul.\"}},{\"@type\":\"ListItem\",\"position\":8,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Buggies no deserto\",\"description\":\"Viveremos a emoção de percorrer as dunas em nosso veículo off-road privado (canam), conduzido por motoristas experientes que o levarão pelas dunas de areia em alta velocidade para desfrutar de vistas panorâmicas impressionantes — 1 hora de percurso.\"}},{\"@type\":\"ListItem\",\"position\":9,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Sandboarding\",\"description\":\"Vamos dominar as dunas com nosso equipamento de sandboarding e deslizar pelas encostas em uma prancha especialmente projetada para a areia. É sem dúvida uma experiência emocionante que você não pode perder. Após esses esportes de aventura, partiremos para Chincha.\"}},{\"@type\":\"ListItem\",\"position\":10,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Chegada a Chincha / Bodega Racimo de Uva\",\"description\":\"Chincha será nossa última parada para degustar alguns macerados de pisco e piscos puros. Você também poderá comprar mamajuanas e experimentar algumas sobremesas típicas de Chincha como tejas e chocotejas.\"}},{\"@type\":\"ListItem\",\"position\":11,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Retorno a Lima\"}},{\"@type\":\"ListItem\",\"position\":12,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Chegada ao seu hotel.\"}}]},\"offers\":{\"@type\":\"Offer\",\"price\":250,\"priceCurrency\":\"USD\",\"availability\":\"https://schema.org/InStock\",\"url\":\"https://www.limaviewtours.com/pt/tours/detalle/tour-privado-huacachina-islas-ballestas-atardecer-buggy-can-am\",\"priceValidUntil\":\"2027-09-01\",\"validFrom\":\"2025-10-21\"}}' WHERE slug='tour-privado-huacachina-islas-ballestas-atardecer-buggy-can-am';
