UPDATE tours SET schema_jsonld_es='{\"@context\":\"https://schema.org\",\"@type\":[\"Product\",\"TouristTrip\"],\"@id\":\"https://www.limaviewtours.com/es/tours/detalle/valle-sagrado-de-los-incas#tour\",\"name\":\"VALLE SAGRADO DE LOS INCAS\",\"description\":\"Experimenta la magia del Valle Sagrado de los Incas y la autenticidad de Chinchero en un tour de un día completo desde Cusco. Sumérgete en la rica cultura y la historia fascinante de los incas mientras exploras mercados tradicionales, ruinas impresionantes y textilerias locales. Un viaje que te tran...\",\"url\":\"https://www.limaviewtours.com/es/tours/detalle/valle-sagrado-de-los-incas\",\"image\":[\"https://www.limaviewtours.com/storage/tours/valle-sagrado-3.png\",\"https://www.limaviewtours.com/storage/tours/valle-sagrado-4.png\",\"https://www.limaviewtours.com/storage/tours/valle-sagrado-5.png\",\"https://www.limaviewtours.com/storage/tours/VALLE-SAGRADO.jpg\"],\"inLanguage\":\"es\",\"touristType\":[\"Sightseeing\",\"Cultural tourism\",\"Adventure\"],\"provider\":{\"@type\":\"TravelAgency\",\"name\":\"Lima View Tours\",\"url\":\"https://www.limaviewtours.com\",\"logo\":\"https://www.limaviewtours.com/assets/logos/logo.png\",\"telephone\":\"+51 925 886 725\"},\"aggregateRating\":{\"@type\":\"AggregateRating\",\"ratingValue\":4.8,\"reviewCount\":1,\"bestRating\":5,\"worstRating\":1},\"itinerary\":{\"@type\":\"ItemList\",\"itemListElement\":[{\"@type\":\"ListItem\",\"position\":1,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Recojo en tu hotel en Cusco por nuestro\",\"description\":\"recojo en tu hotel en Cusco por nuestro guía turístico y conductor.\"}},{\"@type\":\"ListItem\",\"position\":2,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Salida hacia el Valle Sagrado\",\"description\":\"un valle fértil y lleno de historia\"}},{\"@type\":\"ListItem\",\"position\":3,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Traslado a las Ruinas de Pisac\",\"description\":\"un complejo arqueológico inca ubicado en lo alto de la montaña. nuestro guía te llevará en un recorrido por las terrazas agrícolas, templos y el impresionante sistema de irrigación\"}},{\"@type\":\"ListItem\",\"position\":4,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Almuerzo buffet en un restaurante local\",\"description\":\"almuerzo incluido en el precio), donde podrás disfrutar de la deliciosa gastronomía peruana, que combina sabores tradicionales e ingredientes locales frescos\"}},{\"@type\":\"ListItem\",\"position\":5,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Viaje hacia Ollantaytambo\",\"description\":\"un pueblo inca vivo que conserva su diseño urbano original. aquí visitaremos la impresionante fortaleza de Ollantaytambo, un complejo arqueológico que muestra la planificación urbanística inca y ofrece vistas panorámicas del valle\"}},{\"@type\":\"ListItem\",\"position\":6,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Continuaremos nuestro viaje hacia Chinchero\",\"description\":\"un pueblo conocido por su producción de tejidos de alpaca y llama. aquí visitaremos un centro textil donde aprenderemos sobre el proceso de producción de los textiles y tendremos la oportunidad de ver a los artesanos en acción\"}},{\"@type\":\"ListItem\",\"position\":7,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Regreso a Cusco\",\"description\":\"disfrutando del paisaje del Valle Sagrado en el camino de vuelta\"}},{\"@type\":\"ListItem\",\"position\":8,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Llegada a Cusco y traslado de regreso a\",\"description\":\"llegada a Cusco y traslado de regreso a tu hotel, finalizando así nuestro día lleno de descubrimientos en el Valle Sagrado, Ollantaytambo y Chinchero.\"}}]},\"offers\":{\"@type\":\"Offer\",\"price\":75,\"priceCurrency\":\"USD\",\"availability\":\"https://schema.org/InStock\",\"url\":\"https://www.limaviewtours.com/es/tours/detalle/valle-sagrado-de-los-incas\",\"priceValidUntil\":\"2027-09-01\",\"validFrom\":\"2025-11-07\"}}' WHERE slug='valle-sagrado-de-los-incas';
