UPDATE tours SET schema_jsonld_es='{\"@context\":\"https://schema.org\",\"@type\":[\"Product\",\"TouristTrip\"],\"@id\":\"https://www.limaviewtours.com/es/tours/detalle/montana-arcoiris-de-7-colores#tour\",\"name\":\"MONTAÑA ARCOIRIS DE 7 COLORES\",\"description\":\"Embárcate en una jornada inolvidable hacia la Montaña de 7 Colores, una maravilla natural que te dejará sin aliento. Desde Cusco, partimos temprano para llegar a este espectáculo geológico único. Conocida también como Vinicunca, esta montaña debe su colorido a la presencia de minerales que se han de...\",\"url\":\"https://www.limaviewtours.com/es/tours/detalle/montana-arcoiris-de-7-colores\",\"image\":[\"https://www.limaviewtours.com/storage/tours/gallery/01kwg22csazrd3cvk5mjgr342j.webp\",\"https://www.limaviewtours.com/storage/tours/MONTANA-3.png\",\"https://www.limaviewtours.com/storage/tours/MONTANA-2.png\",\"https://www.limaviewtours.com/storage/tours/condor-over-rainbow-hills-2023-11-27-05-23-15-utc.png\",\"https://www.limaviewtours.com/storage/tours/MONTANA-1-1.png\"],\"inLanguage\":\"es\",\"touristType\":[\"Sightseeing\",\"Cultural tourism\",\"Adventure\"],\"provider\":{\"@type\":\"TravelAgency\",\"name\":\"Lima View Tours\",\"url\":\"https://www.limaviewtours.com\",\"logo\":\"https://www.limaviewtours.com/assets/logos/logo.png\",\"telephone\":\"+51 925 886 725\"},\"aggregateRating\":{\"@type\":\"AggregateRating\",\"ratingValue\":4.8,\"reviewCount\":1,\"bestRating\":5,\"worstRating\":1},\"review\":[{\"@type\":\"Review\",\"author\":{\"@type\":\"Person\",\"name\":\"fernando silva\"},\"datePublished\":\"2026-07-18\",\"reviewRating\":{\"@type\":\"Rating\",\"ratingValue\":5,\"bestRating\":5},\"reviewBody\":\"Excelente servicio, todo estuvo muy bien organizado de principio a fin. La montaña es simplemente espectacular, con paisajes increíbles que hacen que la experiencia sea inolvidable. A mi familia le encantó compartir este momento y, especialmente, disfrutar de estar con las alpacas en medio de la mo