UPDATE tours SET schema_jsonld_es='{\"@context\":\"https://schema.org\",\"@type\":[\"Product\",\"TouristTrip\"],\"@id\":\"https://www.limaviewtours.com/es/tours/detalle/laguna-humantay#tour\",\"name\":\"LAGUNA HUMANTAY\",\"description\":\"Embárcate en una experiencia inolvidable hacia uno de los destinos naturales más impresionantes de Perú: la Laguna Humantay. Nuestro tour te llevará a través de majestuosos paisajes de los Andes peruanos, donde podrás disfrutar de vistas panorámicas, explorar la naturaleza en su estado más puro y su...\",\"url\":\"https://www.limaviewtours.com/es/tours/detalle/laguna-humantay\",\"image\":[\"https://www.limaviewtours.com/storage/tours/humantay_1-1-1-1-1.jpg\",\"https://www.limaviewtours.com/storage/tours/laguna-de-humantay-750x536-1.jpg\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwg3qeq4fh1pp7tb0s114ysg.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwg3qek3nm7nr4ahb05hcmaq.webp\",\"https://www.limaviewtours.com/storage/tours/humantay.jpg\",\"https://www.limaviewtours.com/storage/tours/47.jpg\",\"https://www.limaviewtours.com/storage/tours/portada-4.jpg\"],\"inLanguage\":\"es\",\"touristType\":[\"Sightseeing\",\"Cultural tourism\",\"Adventure\"],\"provider\":{\"@type\":\"TravelAgency\",\"name\":\"Lima View Tours\",\"url\":\"https://www.limaviewtours.com\",\"logo\":\"https://www.limaviewtours.com/assets/logos/logo.png\",\"telephone\":\"+51 925 886 725\"},\"aggregateRating\":{\"@type\":\"AggregateRating\",\"ratingValue\":4.9,\"reviewCount\":\"17\",\"bestRating\":5,\"worstRating\":1},\"itinerary\":{\"@type\":\"ItemList\",\"itemListElement\":[{\"@type\":\"ListItem\",\"position\":1,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"5:00 am\",\"description\":\"Recogida en el hotel nuestro servicio de transporte te recogerá en tu hotel en Cusco. Es importante estar listo para salir temprano, ya que la Laguna Humantay se encuentra a cierta distancia y queremos aprovechar al máximo el día.\"}},{\"@type\":\"ListItem\",\"position\":2,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"8:30 am\",\"description\":\"Viaje a la Laguna Humantay disfrutaremos de un pintoresco viaje por los impresionantes paisajes de los andes peruanos mientras nos dirigimos hacia la Laguna Humantay. Se realizarán paradas estratégicas para tomar fotografías y disfrutar de las vistas.\"}},{\"@type\":\"ListItem\",\"position\":3,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"9:00 am\",\"description\":\"Desayuno, llegaremos a un punto de encuentro donde se servirá un desayuno para recargar energías antes de la caminata. (El desayuno buffet esta incluido en el precio)\"}},{\"@type\":\"ListItem\",\"position\":4,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"11:30 am\",\"description\":\"Caminata hacia la Laguna Humantay comenzaremos la caminata hacia la Laguna Humantay. Este trayecto ofrece vistas panorámicas y la oportunidad de apreciar la belleza natural de la región. Se recomienda llevar ropa cómoda y calzado adecuado.\"}},{\"@type\":\"ListItem\",\"position\":5,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"12:30 pm\",\"description\":\"Tiempo libre en la Laguna Humantay, al llegar a la Laguna Humantay, tendrás tiempo libre para explorar, tomar fotografías y disfrutar del entorno natural.\"}},{\"@type\":\"ListItem\",\"position\":6,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"1:30 pm\",\"description\":\"Almuerzo buffet disfrutaremos de un almuerzo buffet con una variedad de opciones para satisfacer diferentes gustos y necesidades dietéticas. (El almuerzo buffet esta incluido en el precio)\"}},{\"@type\":\"ListItem\",\"position\":7,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"4:30 pm\",\"description\":\"Descenso y regreso a Cusco comenzaremos el descenso de regreso al punto de encuentro y luego nos dirigiremos de vuelta a Cusco. En el camino de regreso, aprovecharemos para reflexionar sobre la experiencia y disfrutar de las vistas adicionales.\"}},{\"@type\":\"ListItem\",\"position\":8,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Llegada a Cusco\",\"description\":\"llegaremos a Cusco y te dejaremos cerca a la plaza de armas de Cusco o en tu hotel. El resto de la tarde y la noche quedan libres para que disfrutes de tu tiempo en cusco\"}}]},\"offers\":{\"@type\":\"Offer\",\"price\":50,\"priceCurrency\":\"USD\",\"availability\":\"https://schema.org/InStock\",\"url\":\"https://www.limaviewtours.com/es/tours/detalle/laguna-humantay\",\"priceValidUntil\":\"2027-09-01\",\"validFrom\":\"2025-11-07\"}}' WHERE slug='laguna-humantay';
UPDATE tours SET schema_jsonld_en='{\"@context\":\"https://schema.org\",\"@type\":[\"Product\",\"TouristTrip\"],\"@id\":\"https://www.limaviewtours.com/en/tours/detalle/laguna-humantay#tour\",\"name\":\"HUMANTAY LAKE\",\"description\":\"Embárcate en una experiencia inolvidable hacia uno de los destinos naturales más impresionantes de Perú: la Laguna Humantay. Nuestro tour te llevará a través de majestuosos paisajes de los Andes peruanos, donde podrás disfrutar de vistas panorámicas, explorar la naturaleza en su estado más puro y su...\",\"url\":\"https://www.limaviewtours.com/en/tours/detalle/laguna-humantay\",\"image\":[\"https://www.limaviewtours.com/storage/tours/humantay_1-1-1-1-1.jpg\",\"https://www.limaviewtours.com/storage/tours/laguna-de-humantay-750x536-1.jpg\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwg3qeq4fh1pp7tb0s114ysg.webp\",\"https://www.limaviewtours.com/storage/tours/gallery/01kwg3qek3nm7nr4ahb05hcmaq.webp\",\"https://www.limaviewtours.com/storage/tours/humantay.jpg\",\"https://www.limaviewtours.com/storage/tours/47.jpg\",\"https://www.limaviewtours.com/storage/tours/portada-4.jpg\"],\"inLanguage\":\"en\",\"touristType\":[\"Sightseeing\",\"Cultural tourism\",\"Adventure\"],\"provider\":{\"@type\":\"TravelAgency\",\"name\":\"Lima View Tours\",\"url\":\"https://www.limaviewtours.com\",\"logo\":\"https://www.limaviewtours.com/assets/logos/logo.png\",\"telephone\":\"+51 925 886 725\"},\"aggregateRating\":{\"@type\":\"AggregateRating\",\"ratingValue\":4.9,\"reviewCount\":\"17\",\"bestRating\":5,\"worstRating\":1},\"itinerary\":{\"@type\":\"ItemList\",\"itemListElement\":[{\"@type\":\"ListItem\",\"position\":1,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"5:00 am\",\"description\":\"Hotel pickup — our transport service will pick you up at your hotel in Cusco. It is important to be ready to leave early, as Laguna Humantay is some distance away and we want to make the most of the day.\"}},{\"@type\":\"ListItem\",\"position\":2,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"8:30 am\",\"description\":\"Journey to Laguna Humantay — enjoy a scenic drive through the stunning landscapes of the Peruvian Andes on the way to Laguna Humantay. Strategic stops will be made for photos and to take in the views.\"}},{\"@type\":\"ListItem\",\"position\":3,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"9:00 am\",\"description\":\"Breakfast — we will arrive at a meeting point where a buffet breakfast will be served to fuel up before the hike. (Buffet breakfast included in the price.)\"}},{\"@type\":\"ListItem\",\"position\":4,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"11:30 am\",\"description\":\"Hike to Laguna Humantay — we begin the hike toward Laguna Humantay. The trail offers panoramic views and the chance to appreciate the natural beauty of the region. Comfortable clothing and proper footwear are recommended.\"}},{\"@type\":\"ListItem\",\"position\":5,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"12:30 pm\",\"description\":\"Free time at Laguna Humantay — upon arriving at Laguna Humantay, you will have free time to explore, take photos, and soak in the natural surroundings.\"}},{\"@type\":\"ListItem\",\"position\":6,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"1:30 pm\",\"description\":\"Buffet lunch — we will enjoy a buffet lunch with a variety of options to suit different tastes and dietary needs. (Buffet lunch included in the price.)\"}},{\"@type\":\"ListItem\",\"position\":7,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"4:30 pm\",\"description\":\"Descent and return to Cusco — we begin the descent back to the meeting point and then make our way back to Cusco. On the way back, we\'ll take the time to reflect on the experience and enjoy additional views.\"}},{\"@type\":\"ListItem\",\"position\":8,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Arrival in Cusco\",\"description\":\"we will arrive in Cusco and drop you off near the Plaza de Armas or at your hotel. The rest of the afternoon and evening are free for you to enjoy Cusco at your own pace\"}}]},\"offers\":{\"@type\":\"Offer\",\"price\":50,\"priceCurrency\":\"USD\",\"availability\":\"https://schema.org/InStock\",\"url\":\"https://www.limaviewtours.com/en/tours/detalle/laguna-humantay\",\"priceValidUntil\":\"2027-09-01\",\"validFrom\":\"2025-11-07\"}}' WHERE slug='laguna-humantay';
