UPDATE tours SET schema_jsonld_es='{\"@context\":\"https://schema.org\",\"@type\":[\"Product\",\"TouristTrip\"],\"@id\":\"https://www.limaviewtours.com/es/tours/detalle/conoce-machu-picchu-si-no-tienes-entrada#tour\",\"name\":\"CONOCE MACHU PICCHU SI NO TIENES ENTRADA\",\"description\":\"Descubre la majestuosidad de Machu Picchu en un tour de 2 días desde Cusco. En este viaje, disfrutarás de un pintoresco viaje en tren hacia Aguas Calientes, el pueblo base para explorar Machu Picchu. Conoce la historia y la cultura de esta antigua ciudad inca en una visita guiada, y disfruta de tiem...\",\"url\":\"https://www.limaviewtours.com/es/tours/detalle/conoce-machu-picchu-si-no-tienes-entrada\",\"image\":[\"https://www.limaviewtours.com/storage/tours/PICCHU-SI-NO-TIENES-ENTRADA-9.jpg\",\"https://www.limaviewtours.com/storage/tours/PICCHU-SI-NO-TIENES-ENTRADA-1.jpg\",\"https://www.limaviewtours.com/storage/tours/PICCHU-SI-NO-TIENES-ENTRADA-3.jpg\",\"https://www.limaviewtours.com/storage/tours/PICCHU-SI-NO-TIENES-ENTRADA-4.jpg\",\"https://www.limaviewtours.com/storage/tours/PICCHU-SI-NO-TIENES-ENTRADA-5.jpg\",\"https://www.limaviewtours.com/storage/tours/PICCHU-SI-NO-TIENES-ENTRADA-6.jpg\",\"https://www.limaviewtours.com/storage/tours/PICCHU-SI-NO-TIENES-ENTRADA-7.jpg\"],\"inLanguage\":\"es\",\"touristType\":[\"Sightseeing\",\"Cultural tourism\",\"Adventure\"],\"provider\":{\"@type\":\"TravelAgency\",\"name\":\"Lima View Tours\",\"url\":\"https://www.limaviewtours.com\",\"logo\":\"https://www.limaviewtours.com/assets/logos/logo.png\",\"telephone\":\"+51 925 886 725\"},\"aggregateRating\":{\"@type\":\"AggregateRating\",\"ratingValue\":4.8,\"reviewCount\":1,\"bestRating\":5,\"worstRating\":1},\"itinerary\":{\"@type\":\"ItemList\",\"itemListElement\":[{\"@type\":\"ListItem\",\"position\":1,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Recojo a hotel\",\"description\":\"Daremos inicio recogiendolo en el lobby de tu hotel para iniciar nuestro recorrido\"}},{\"@type\":\"ListItem\",\"position\":2,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Viaje a Ollantaytambo\",\"description\":\"luego de recogerlos del hotel daremos inicio a nuestro traslado desde cusco en una cómoda movilidad hacia la estación del tren en el pueblo de Ollantaytambo (2h 30min de viaje aproximadamente).\"}},{\"@type\":\"ListItem\",\"position\":3,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Llegada a Ollantaytambo\",\"description\":\"Desde allí, nos embarcaremos en un panorámico viaje pintoresco en tren hacia aguas calientes, el encantador pueblo situado al pie de Machu Picchu.\"}},{\"@type\":\"ListItem\",\"position\":4,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Llegada a aguas calientes\",\"description\":\"Al llegar al pueblo de Aguas Calientes nuestro guía estara esperandolos en la estación con un cartel con tu nombre para darles una comoda bienvenida luego les dara las indicaciones correspondiente seguidamente nos registraremos en el hotel. Luego podran disfrutar de un tiempo libre para relajarse y explorar este pintoresco pueblo, lleno de coloridas calles y encantadoras tiendas locales.\"}},{\"@type\":\"ListItem\",\"position\":5,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Pernocte en Aguas Calientes\",\"description\":\"Por la noche, podrán salir a disfrutar de una deliciosa cena en uno de los restaurantes locales, donde podrás probar la auténtica cocina peruana al termino pernoctaran en el hotel (incluido en el precio) y se prepararan para la emocionante jornada del día siguiente.\"}},{\"@type\":\"ListItem\",\"position\":6,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Bus de Aguas Calientes a Machu Picchu\",\"description\":\"Después de un temprano desayuno, abordaremos el autobús que nos llevará desde el pueblo de aguas caliente a la entrada de Machu Picchu, donde comenzará nuestra aventura en esta maravilla arqueológica.\"}},{\"@type\":\"ListItem\",\"position\":7,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"La entrada a Machu Picchu esta sujeto al horario de ingreso que coordinemos con el pasajero\",\"description\":\"Al ingresar a la Llaqta recorreremos Machu Picchu con nuestro guía experto que nos llevará a través de los principales puntos de interés de la Llaqta de Machu Picchu( duracion de 2 a 3 horas aproximadamente) hasta terminar de recorrer toda la ciudadela, contándonos la fascinante historia y la cultura de esta antigua ciudad inca. También tendrás tiempo libre para explorar por tu cuenta, tomar fotos y sumergirte en la mística atmósfera de este lugar arquitectonico único.\"}},{\"@type\":\"ListItem\",\"position\":8,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Tarde libre\",\"description\":\"Regresaremos a aguas calientes en autobús, donde tendrás tiempo libre para almorzar y comprar algunos recuerdos de tu visita a Machu Picchu.\"}},{\"@type\":\"ListItem\",\"position\":9,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\":00 pm regreso a Ollantaytambo\",\"description\":\"Por la tarde, abordaremos el tren de regreso a Ollantaytambo, disfrutando de las impresionantes vistas panorámicas en el camino de regreso.\"}},{\"@type\":\"ListItem\",\"position\":10,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Llegada a Ollantaytambo\",\"description\":\"una vez en Ollantaytambo, serás trasladado de regreso a cusco en un bus a cargo de la empresa Inca Rail\"}},{\"@type\":\"ListItem\",\"position\":11,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Llegada a Cusco\",\"description\":\"una vez que llegue a la estacion del bus en cusco te recogeremos y trasladaremos a tu hotel donde podrás descansar y reflexionar sobre esta inolvidable experiencia en Machu Picchu.\"}}]},\"offers\":{\"@type\":\"Offer\",\"price\":500,\"priceCurrency\":\"USD\",\"availability\":\"https://schema.org/InStock\",\"url\":\"https://www.limaviewtours.com/es/tours/detalle/conoce-machu-picchu-si-no-tienes-entrada\",\"priceValidUntil\":\"2027-09-01\",\"validFrom\":\"2025-11-07\"}}' WHERE slug='conoce-machu-picchu-si-no-tienes-entrada';
UPDATE tours SET schema_jsonld_en='{\"@context\":\"https://schema.org\",\"@type\":[\"Product\",\"TouristTrip\"],\"@id\":\"https://www.limaviewtours.com/en/tours/detalle/conoce-machu-picchu-si-no-tienes-entrada#tour\",\"name\":\"VISIT MACHU PICCHU IF YOU DO NOT HAVE A TICKET\",\"description\":\"Descubre la majestuosidad de Machu Picchu en un tour de 2 días desde Cusco. En este viaje, disfrutarás de un pintoresco viaje en tren hacia Aguas Calientes, el pueblo base para explorar Machu Picchu. Conoce la historia y la cultura de esta antigua ciudad inca en una visita guiada, y disfruta de tiem...\",\"url\":\"https://www.limaviewtours.com/en/tours/detalle/conoce-machu-picchu-si-no-tienes-entrada\",\"image\":[\"https://www.limaviewtours.com/storage/tours/PICCHU-SI-NO-TIENES-ENTRADA-9.jpg\",\"https://www.limaviewtours.com/storage/tours/PICCHU-SI-NO-TIENES-ENTRADA-1.jpg\",\"https://www.limaviewtours.com/storage/tours/PICCHU-SI-NO-TIENES-ENTRADA-3.jpg\",\"https://www.limaviewtours.com/storage/tours/PICCHU-SI-NO-TIENES-ENTRADA-4.jpg\",\"https://www.limaviewtours.com/storage/tours/PICCHU-SI-NO-TIENES-ENTRADA-5.jpg\",\"https://www.limaviewtours.com/storage/tours/PICCHU-SI-NO-TIENES-ENTRADA-6.jpg\",\"https://www.limaviewtours.com/storage/tours/PICCHU-SI-NO-TIENES-ENTRADA-7.jpg\"],\"inLanguage\":\"en\",\"touristType\":[\"Sightseeing\",\"Cultural tourism\",\"Adventure\"],\"provider\":{\"@type\":\"TravelAgency\",\"name\":\"Lima View Tours\",\"url\":\"https://www.limaviewtours.com\",\"logo\":\"https://www.limaviewtours.com/assets/logos/logo.png\",\"telephone\":\"+51 925 886 725\"},\"aggregateRating\":{\"@type\":\"AggregateRating\",\"ratingValue\":4.8,\"reviewCount\":1,\"bestRating\":5,\"worstRating\":1},\"itinerary\":{\"@type\":\"ItemList\",\"itemListElement\":[{\"@type\":\"ListItem\",\"position\":1,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Hotel pickup\",\"description\":\"We\'ll begin by picking you up at your hotel lobby to start our tour.\"}},{\"@type\":\"ListItem\",\"position\":2,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Journey to Ollantaytambo\",\"description\":\"After picking you up from the hotel, we\'ll start our transfer from Cusco in a comfortable vehicle to the train station in the town of Ollantaytambo (approximately 2h 30min journey).\"}},{\"@type\":\"ListItem\",\"position\":3,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Arrival at Ollantaytambo\",\"description\":\"From there, we\'ll board a scenic panoramic train to Aguas Calientes, the charming town nestled at the foot of Machu Picchu.\"}},{\"@type\":\"ListItem\",\"position\":4,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Arrival at Aguas Calientes\",\"description\":\"Upon arriving at Aguas Calientes, our guide will be waiting at the station with a sign bearing your name to give you a warm welcome. After receiving instructions, we\'ll check in to the hotel. You\'ll then have free time to relax and explore this picturesque town, full of colorful streets and charming local shops.\"}},{\"@type\":\"ListItem\",\"position\":5,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Overnight stay in Aguas Calientes\",\"description\":\"In the evening, you\'ll be free to enjoy a delicious dinner at one of the local restaurants, where you can taste authentic Peruvian cuisine. Afterward, you\'ll spend the night at the hotel (included in the price) and get ready for the exciting day ahead.\"}},{\"@type\":\"ListItem\",\"position\":6,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Bus from Aguas Calientes to Machu Picchu\",\"description\":\"After an early breakfast, we\'ll board the bus that will take us from the town of Aguas Calientes to the entrance of Machu Picchu, where our adventure in this archaeological wonder begins.\"}},{\"@type\":\"ListItem\",\"position\":7,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Machu Picchu entry is subject to the admission schedule coordinated with the passenger\",\"description\":\"Upon entering the Llaqta, we\'ll explore Machu Picchu with our expert guide, who will lead us through the main highlights of the Llaqta de Machu Picchu (approximately 2 to 3 hours) until we\'ve toured the entire citadel, learning about the fascinating history and culture of this ancient Inca city. You\'ll also have free time to explore on your own, take photos, and soak in the mystical atmosphere of this unique architectural site.\"}},{\"@type\":\"ListItem\",\"position\":8,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Free afternoon\",\"description\":\"We\'ll return to Aguas Calientes by bus, where you\'ll have free time to have lunch and pick up some souvenirs from your visit to Machu Picchu.\"}},{\"@type\":\"ListItem\",\"position\":9,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\":00 pm return to Ollantaytambo\",\"description\":\"In the afternoon, we\'ll board the train back to Ollantaytambo, enjoying the stunning panoramic views on the way back.\"}},{\"@type\":\"ListItem\",\"position\":10,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Arrival at Ollantaytambo\",\"description\":\"Once in Ollantaytambo, you\'ll be transferred back to Cusco by bus operated by Inca Rail.\"}},{\"@type\":\"ListItem\",\"position\":11,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Arrival at Cusco\",\"description\":\"Once you arrive at the bus station in Cusco, we\'ll pick you up and transfer you to your hotel, where you can rest and reflect on this unforgettable experience at Machu Picchu.\"}}]},\"offers\":{\"@type\":\"Offer\",\"price\":500,\"priceCurrency\":\"USD\",\"availability\":\"https://schema.org/InStock\",\"url\":\"https://www.limaviewtours.com/en/tours/detalle/conoce-machu-picchu-si-no-tienes-entrada\",\"priceValidUntil\":\"2027-09-01\",\"validFrom\":\"2025-11-07\"}}' WHERE slug='conoce-machu-picchu-si-no-tienes-entrada';
UPDATE tours SET schema_jsonld_pt='{\"@context\":\"https://schema.org\",\"@type\":[\"Product\",\"TouristTrip\"],\"@id\":\"https://www.limaviewtours.com/pt/tours/detalle/conoce-machu-picchu-si-no-tienes-entrada#tour\",\"name\":\"CONHEÇA MACHU PICCHU SEM ENTRADA\",\"description\":\"Descubre la majestuosidad de Machu Picchu en un tour de 2 días desde Cusco. En este viaje, disfrutarás de un pintoresco viaje en tren hacia Aguas Calientes, el pueblo base para explorar Machu Picchu. Conoce la historia y la cultura de esta antigua ciudad inca en una visita guiada, y disfruta de tiem...\",\"url\":\"https://www.limaviewtours.com/pt/tours/detalle/conoce-machu-picchu-si-no-tienes-entrada\",\"image\":[\"https://www.limaviewtours.com/storage/tours/PICCHU-SI-NO-TIENES-ENTRADA-9.jpg\",\"https://www.limaviewtours.com/storage/tours/PICCHU-SI-NO-TIENES-ENTRADA-1.jpg\",\"https://www.limaviewtours.com/storage/tours/PICCHU-SI-NO-TIENES-ENTRADA-3.jpg\",\"https://www.limaviewtours.com/storage/tours/PICCHU-SI-NO-TIENES-ENTRADA-4.jpg\",\"https://www.limaviewtours.com/storage/tours/PICCHU-SI-NO-TIENES-ENTRADA-5.jpg\",\"https://www.limaviewtours.com/storage/tours/PICCHU-SI-NO-TIENES-ENTRADA-6.jpg\",\"https://www.limaviewtours.com/storage/tours/PICCHU-SI-NO-TIENES-ENTRADA-7.jpg\"],\"inLanguage\":\"pt\",\"touristType\":[\"Sightseeing\",\"Cultural tourism\",\"Adventure\"],\"provider\":{\"@type\":\"TravelAgency\",\"name\":\"Lima View Tours\",\"url\":\"https://www.limaviewtours.com\",\"logo\":\"https://www.limaviewtours.com/assets/logos/logo.png\",\"telephone\":\"+51 925 886 725\"},\"aggregateRating\":{\"@type\":\"AggregateRating\",\"ratingValue\":4.8,\"reviewCount\":1,\"bestRating\":5,\"worstRating\":1},\"itinerary\":{\"@type\":\"ItemList\",\"itemListElement\":[{\"@type\":\"ListItem\",\"position\":1,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Busca no hotel\",\"description\":\"Começaremos buscando você no saguão do seu hotel para iniciar nosso roteiro.\"}},{\"@type\":\"ListItem\",\"position\":2,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Viagem para Ollantaytambo\",\"description\":\"Após buscá-lo no hotel, iniciaremos nosso traslado de Cusco em um confortável veículo até a estação de trem na cidade de Ollantaytambo (aproximadamente 2h 30min de viagem).\"}},{\"@type\":\"ListItem\",\"position\":3,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Chegada a Ollantaytambo\",\"description\":\"De lá, embarcaremos em uma pitoresca viagem panorâmica de trem até Aguas Calientes, a encantadora cidade situada aos pés de Machu Picchu.\"}},{\"@type\":\"ListItem\",\"position\":4,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Chegada a Aguas Calientes\",\"description\":\"Ao chegar a Aguas Calientes, nosso guia estará esperando na estação com uma placa com seu nome para recebê-lo confortavelmente. Após as instruções, faremos o check-in no hotel. Em seguida, você terá tempo livre para relaxar e explorar esta pitoresca cidade, cheia de ruas coloridas e encantadoras lojas locais.\"}},{\"@type\":\"ListItem\",\"position\":5,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Pernoite em Aguas Calientes\",\"description\":\"À noite, você poderá sair para desfrutar de um delicioso jantar em um dos restaurantes locais, onde poderá experimentar a autêntica culinária peruana. Em seguida, passará a noite no hotel (incluído no preço) e se preparará para o emocionante dia seguinte.\"}},{\"@type\":\"ListItem\",\"position\":6,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Ônibus de Aguas Calientes para Machu Picchu\",\"description\":\"Após um café da manhã cedo, embarcaremos no ônibus que nos levará da cidade de Aguas Calientes até a entrada de Machu Picchu, onde começará nossa aventura nesta maravilha arqueológica.\"}},{\"@type\":\"ListItem\",\"position\":7,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"O horário de entrada em Machu Picchu está sujeito ao agendamento acordado com o passageiro\",\"description\":\"Ao entrar na Llaqta, percorreremos Machu Picchu com nosso guia especialista, que nos conduzirá pelos principais pontos de interesse da Llaqta de Machu Picchu (duração aproximada de 2 a 3 horas) até completar o percurso pela cidadela, contando a fascinante história e cultura desta antiga cidade inca. Você também terá tempo livre para explorar por conta própria, tirar fotos e se deixar envolver pela mística atmosfera deste lugar arquitetônico único.\"}},{\"@type\":\"ListItem\",\"position\":8,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Tarde livre\",\"description\":\"Retornaremos a Aguas Calientes de ônibus, onde você terá tempo livre para almoçar e comprar algumas lembranças da sua visita a Machu Picchu.\"}},{\"@type\":\"ListItem\",\"position\":9,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\":00 pm retorno para Ollantaytambo\",\"description\":\"À tarde, embarcaremos no trem de volta para Ollantaytambo, aproveitando as impressionantes vistas panorâmicas no caminho de regresso.\"}},{\"@type\":\"ListItem\",\"position\":10,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Chegada a Ollantaytambo\",\"description\":\"Em Ollantaytambo, você será transferido de volta a Cusco em um ônibus operado pela Inca Rail.\"}},{\"@type\":\"ListItem\",\"position\":11,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Chegada a Cusco\",\"description\":\"Ao chegar à rodoviária em Cusco, buscaremos você e o transferiremos ao seu hotel, onde poderá descansar e refletir sobre esta inesquecível experiência em Machu Picchu.\"}}]},\"offers\":{\"@type\":\"Offer\",\"price\":500,\"priceCurrency\":\"USD\",\"availability\":\"https://schema.org/InStock\",\"url\":\"https://www.limaviewtours.com/pt/tours/detalle/conoce-machu-picchu-si-no-tienes-entrada\",\"priceValidUntil\":\"2027-09-01\",\"validFrom\":\"2025-11-07\"}}' WHERE slug='conoce-machu-picchu-si-no-tienes-entrada';
UPDATE tours SET schema_jsonld_es='{\"@context\":\"https://schema.org\",\"@type\":[\"Product\",\"TouristTrip\"],\"@id\":\"https://www.limaviewtours.com/es/tours/detalle/machu-picchu-2-dias-1-noches#tour\",\"name\":\"TOUR PRIVADO DE 2 DÍAS A MACHU PICCHU  (TODO INCLUIDO)\",\"description\":\"Descubre la majestuosidad de Machu Picchu en un tour de 2 días desde Cusco. En este viaje, disfrutarás de un pintoresco viaje en tren hacia Aguas Calientes, el pueblo base para explorar Machu Picchu. Conoce la historia y la cultura de esta antigua ciudad inca en una visita guiada, y disfruta de tiem...\",\"url\":\"https://www.limaviewtours.com/es/tours/detalle/machu-picchu-2-dias-1-noches\",\"image\":[\"https://www.limaviewtours.com/storage/tours/3.jpg\",\"https://www.limaviewtours.com/storage/tours/5.jpg\",\"https://www.limaviewtours.com/storage/tours/4.jpg\",\"https://www.limaviewtours.com/storage/tours/MACHU-2-DIAS-1.jpg\",\"https://www.limaviewtours.com/storage/tours/1.jpg\",\"https://www.limaviewtours.com/storage/tours/2.jpg\"],\"inLanguage\":\"es\",\"touristType\":[\"Sightseeing\",\"Cultural tourism\",\"Adventure\"],\"provider\":{\"@type\":\"TravelAgency\",\"name\":\"Lima View Tours\",\"url\":\"https://www.limaviewtours.com\",\"logo\":\"https://www.limaviewtours.com/assets/logos/logo.png\",\"telephone\":\"+51 925 886 725\"},\"aggregateRating\":{\"@type\":\"AggregateRating\",\"ratingValue\":4.8,\"reviewCount\":1,\"bestRating\":5,\"worstRating\":1},\"itinerary\":{\"@type\":\"ItemList\",\"itemListElement\":[{\"@type\":\"ListItem\",\"position\":1,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Recojo a hotel\",\"description\":\"Daremos inicio recogiendolo en el lobby de tu hotel para iniciar nuestro recorrido\"}},{\"@type\":\"ListItem\",\"position\":2,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Viaje a Ollantaytambo\",\"description\":\"luego de recogerlos del hotel daremos inicio a nuestro traslado desde cusco en una cómoda movilidad hacia la estación del tren en el pueblo de Ollantaytambo (2h 30min de viaje aproximadamente).\"}},{\"@type\":\"ListItem\",\"position\":3,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Llegada a Ollantaytambo\",\"description\":\"Desde allí, nos embarcaremos en un panorámico viaje pintoresco en tren hacia aguas calientes, el encantador pueblo situado al pie de Machu Picchu.\"}},{\"@type\":\"ListItem\",\"position\":4,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Llegada a aguas calientes\",\"description\":\"Al llegar al pueblo de Aguas Calientes nuestro guía estara esperandolos en la estación con un cartel con tu nombre para darles una comoda bienvenida luego les dara las indicaciones correspondiente seguidamente nos registraremos en el hotel. Luego podran disfrutar de un tiempo libre para relajarse y explorar este pintoresco pueblo, lleno de coloridas calles y encantadoras tiendas locales.\"}},{\"@type\":\"ListItem\",\"position\":5,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Pernocte en Aguas Calientes\",\"description\":\"Por la noche, podrán salir a disfrutar de una deliciosa cena en uno de los restaurantes locales, donde podrás probar la auténtica cocina peruana (comida no incluida en el precio) al termino pernoctaran en el hotel indicado (hotel incluido en el precio) y se prepararan para la emocionante jornada del día siguiente.\"}},{\"@type\":\"ListItem\",\"position\":6,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Bus de Aguas Calientes a Machu Picchu\",\"description\":\"Después de un temprano desayuno, abordaremos el autobús que nos llevará desde el pueblo de aguas caliente a la entrada de Machu Picchu, donde comenzará nuestra aventura en esta maravilla arqueológica.\"}},{\"@type\":\"ListItem\",\"position\":7,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"La entrada a Machu Picchu esta sujeto al horario de ingreso que coordinemos con el pasajero\",\"description\":\"Al ingresar a la Llaqta recorreremos Machu Picchu con nuestro guía experto que nos llevará a través de los principales puntos de interés de la Llaqta de Machu Picchu( duracion de 2 a 3 horas aproximadamente) hasta terminar de recorrer toda la ciudadela, contándonos la fascinante historia y la cultura de esta antigua ciudad inca. También tendrás tiempo libre para explorar por tu cuenta, tomar fotos y sumergirte en la mística atmósfera de este lugar arquitectonico único.\"}},{\"@type\":\"ListItem\",\"position\":8,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Tarde libre\",\"description\":\"Regresaremos a aguas calientes en autobús, donde tendrás tiempo libre para almorzar y comprar algunos recuerdos de tu visita a Machu Picchu.\"}},{\"@type\":\"ListItem\",\"position\":9,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Regreso a Ollantaytambo\",\"description\":\"Por la tarde, abordaremos el tren de regreso a Ollantaytambo, disfrutando de las impresionantes vistas panorámicas en el camino de regreso.\"}},{\"@type\":\"ListItem\",\"position\":10,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Llegada a Ollantaytambo\",\"description\":\"una vez en Ollantaytambo, serás trasladado de regreso a cusco en un bus a cargo de la empresa Inca Rail\"}},{\"@type\":\"ListItem\",\"position\":11,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"Llegada a Cusco\",\"description\":\"una vez que llegue a la estacion del bus en cusco te recogeremos y trasladaremos a tu hotel donde podrás descansar y reflexionar sobre esta inolvidable experiencia en Machu Picchu.\"}}]},\"offers\":{\"@type\":\"Offer\",\"price\":550,\"priceCurrency\":\"USD\",\"availability\":\"https://schema.org/InStock\",\"url\":\"https://www.limaviewtours.com/es/tours/detalle/machu-picchu-2-dias-1-noches\",\"priceValidUntil\":\"2027-09-01\",\"validFrom\":\"2025-11-07\"}}' WHERE slug='machu-picchu-2-dias-1-noches';
