UPDATE tours SET schema_jsonld_es='{\"@context\":\"https://schema.org\",\"@type\":[\"Product\",\"TouristTrip\"],\"@id\":\"https://www.limaviewtours.com/es/tours/detalle/paquete-cusco-4-dias-con-machu-picchu-humantay-y-montana-7-colores-lima-view-tours#tour\",\"name\":\"Paquete Cusco 4 Días con Machu Picchu, Humantay y Montaña de 7 Colores\",\"description\":\"Descubre lo mejor de Cusco en un viaje de 4 días y 3 noches que combina historia, paisajes andinos y una visita inolvidable a Machu Picchu. Este paquete incluye City Tour en Cusco, Montaña de 7 Colores, Laguna Humantay, hotel, traslados y entradas, ideal para quienes buscan una experiencia completa,...\",\"url\":\"https://www.limaviewtours.com/es/tours/detalle/paquete-cusco-4-dias-con-machu-picchu-humantay-y-montana-7-colores-lima-view-tours\",\"image\":[\"https://www.limaviewtours.com/storage/tours/machu-picchu-paquete-de-4-dias-lima-view-tours.jpg\",\"https://www.limaviewtours.com/storage/tours/paquete-cusco-de-4-dias-lima-view-tours.jpg\",\"https://www.limaviewtours.com/storage/tours/paquete-en-cusco-de-4-dias.webp\",\"https://www.limaviewtours.com/storage/tours/MACHU-PICCHU-4-DIAS-Y-3-NOCHES-LIMA-VIEW-TOURS.webp\",\"https://www.limaviewtours.com/storage/tours/paquete-en-cusco-de-4-dias-lima-view-tours.jpg\",\"https://www.limaviewtours.com/storage/tours/Laguna-Humantay.jpeg\",\"https://www.limaviewtours.com/storage/tours/Quito_-Ecuador_.jpeg\"],\"inLanguage\":\"es\",\"touristType\":[\"Sightseeing\",\"Cultural tourism\",\"Adventure\"],\"provider\":{\"@type\":\"TravelAgency\",\"name\":\"Lima View Tours\",\"url\":\"https://www.limaviewtours.com\",\"logo\":\"https://www.limaviewtours.com/assets/logos/logo.png\",\"telephone\":\"+51 925 886 725\"},\"aggregateRating\":{\"@type\":\"AggregateRating\",\"ratingValue\":4.8,\"reviewCount\":1,\"bestRating\":5,\"worstRating\":1},\"itinerary\":{\"@type\":\"ItemList\",\"itemListElement\":[{\"@type\":\"ListItem\",\"position\":1,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"DIA 1: RECOJO DEL AEROPUERTO Y CITY TOUR POR LAS TARDE\",\"description\":\"Recepción en el aeropuerto y traslado al hotel. Tiempo libre para aclimatación. Al mediodía, City Tour por Cusco con visita a Qoricancha, Sacsayhuamán, Qenqo, Puka Pukara, Tambomachay y vista panorámica de la Catedral. Noche en Cusco. (HOTEL 3 ESTRELLAS INCLUIDO)\"}},{\"@type\":\"ListItem\",\"position\":2,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"DÍA 2: MONTAÑA DE 7 COLORES\",\"description\":\"Recojo temprano, desayuno en ruta y excursión a Vinicunca, uno de los paisajes más impresionantes de Cusco. Tiempo para fotografías, almuerzo buffet y retorno por la tarde. Noche en Cusco. (HOTEL 3 ESTRELLAS INCLUIDO)\"}},{\"@type\":\"ListItem\",\"position\":3,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"DÍA 3: MACHU PICCHU TOUR DE DIA COMPLETO\",\"description\":\"Salida desde Cusco hacia la estación de tren en Ollantaytambo para continuar el viaje a Aguas Calientes. Luego se realiza el ascenso en bus a Machu Picchu, donde disfrutarán de una visita guiada por la ciudadela con una duración aproximada de 2 a 3 horas. Después tendrán tiempo libre para fotos y para disfrutar el entorno antes del retorno en bus y tren hacia Cusco. \\\"En Lima View Tours\\\", este tour incluye tren, bus, entrada a Machu Picchu y guía profesional.Noche en Cusco. (HOTEL 3 ESTRELLAS INCLUIDO)\"}},{\"@type\":\"ListItem\",\"position\":4,\"item\":{\"@type\":\"TouristAttraction\",\"name\":\"DÍA 4: LAGUNA HUMANTAY Y TRASLADO AL AEROPUERTO\",\"description\":\"En el último día visitaremos la espectacular Laguna Humantay, famosa por sus aguas turquesas y paisajes de montaña. Después de la excursión y del tiempo para disfrutar el lugar, se realizará el retorno y el traslado correspondiente para el aeropuerto.\"}}]},\"offers\":{\"@type\":\"Offer\",\"price\":1200,\"priceCurrency\":\"USD\",\"availability\":\"https://schema.org/InStock\",\"url\":\"https://www.limaviewtours.com/es/tours/detalle/paquete-cusco-4-dias-con-machu-picchu-humantay-y-montana-7-colores-lima-view-tours\",\"priceValidUntil\":\"2027-09-01\",\"validFrom\":\"2026-03-31\"}}' WHERE slug='paquete-cusco-4-dias-con-machu-picchu-humantay-y-montana-7-colores-lima-view-tours';
